#[test]

    fn web_tools_survive_the_inline_cap() {
        // A real catalogue is larger than the inline cap, so web access must
        // not depend on the model calling find_tools first.
        let mut defs: Vec<ToolDefinition> = (0..300)
            .map(|i| ToolDefinition {
                name: format!("tool_{i}"),
                description: "d".to_string(),
                parameters: serde_json::json!({"type": "object"}),
            })
            .collect();
        for name in ["web_search", "web_fetch"] {
            defs.push(ToolDefinition {
                name: name.to_string(),
                description: "web".to_string(),
                parameters: serde_json::json!({"type": "object"}),
            });
        }
        let active = initial_active_tools(&defs, true);
        for name in ["web_search", "web_fetch"] {
            assert!(
                active.iter().any(|tool| tool.name == name),
                "{name} missing from the inline set"
            );
        }
    }

    #[test]
    fn step_cap_defaults_to_500_and_zero_means_no_cap() {
        // 500 is the shipped default so a long turn is not cut off mid-work.
        assert_eq!(DEFAULT_MAX_TURN_ITERATIONS, 500);
        assert_eq!(normalize_step_cap(DEFAULT_MAX_TURN_ITERATIONS), 500);
        // A subagent may outlive a metered parent turn, but never the
        // subscription ceiling, and it always stays inside the clamp.
        // Both bounds are constants, so assert at compile time: a regression
        // now fails the build instead of only the test run.
        const {
            assert!(SUBAGENT_MAX_ITERATIONS > DEFAULT_MAX_TURN_ITERATIONS);
        }
        assert_eq!(
            normalize_step_cap(SUBAGENT_MAX_ITERATIONS),
            SUBAGENT_MAX_ITERATIONS
        );
        // 0 disables the cap; the loop then never trips its step guard.
        assert_eq!(normalize_step_cap(0), UNLIMITED_TURN_ITERATIONS);
        // Anything else keeps the documented clamp.
        assert_eq!(normalize_step_cap(1), 1);
        assert_eq!(normalize_step_cap(20_000), 10_000);
    }

    #[test]
    fn subscription_providers_get_the_deeper_cap() {
        // Termigo parity: OAuth / keyless providers are bounded by their
        // own usage window, so they get 10_000 steps; a metered API-key
        // provider keeps 500.
        for name in [
            "openai-codex",
            "chatgpt",
            "claude-oauth",
            "antigravity",
            "xai-oauth",
            "github-copilot",
            "copilot",
            "muse-something",
        ] {
            assert!(is_unmetered_provider(name), "{name} should be unmetered");
            assert_eq!(default_step_cap_for(name), OAUTH_MAX_TURN_ITERATIONS);
        }
        for name in ["default", "mistral", "openai", "openrouter", "odon-auto"] {
            assert!(!is_unmetered_provider(name), "{name} is metered");
            assert_eq!(default_step_cap_for(name), DEFAULT_MAX_TURN_ITERATIONS);
        }
        // The deeper cap still obeys the documented clamp.
        assert_eq!(
            normalize_step_cap(OAUTH_MAX_TURN_ITERATIONS),
            OAUTH_MAX_TURN_ITERATIONS
        );
    }
}

use odon_core::MessageAttachment;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use tokio::sync::Notify;

/// A user message injected into a running agent turn.
#[derive(Debug, Clone)]
pub struct SteerMessage {
    pub id: String,
    pub text: String,
    pub attachments: Vec<MessageAttachment>,
    /// Priority steers interrupt the current provider stream so the guidance is
    /// applied immediately instead of waiting for the next tool step.
    pub priority: bool,
}

/// Thread-safe steer mailbox shared between the HTTP handlers and the agent
/// loop.
#[derive(Clone, Default)]
pub struct SteerQueue {
    messages: Arc<Mutex<Vec<SteerMessage>>>,
    priority: Arc<AtomicBool>,
    notify: Arc<Notify>,
}

impl SteerQueue {
    pub fn new() -> Self {
        Self::default()
    }

    /// Insert or update a steer by id. Updating an existing steer to priority
    /// wakes the running turn so it can preempt the current stream.
    pub fn push(&self, message: SteerMessage) {
        let mut messages = self.messages.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(existing) = messages.iter_mut().find(|item| item.id == message.id) {
            existing.text = message.text;
            existing.attachments = message.attachments;
            if message.priority {
                existing.priority = true;
                self.priority.store(true, Ordering::SeqCst);
                // notify_one stores a permit when nobody is waiting yet,
                // so the wakeup is not lost in the check-then-wait race.
                self.notify.notify_one();
            }
            return;
        }
        if message.priority {
            self.priority.store(true, Ordering::SeqCst);
        }
        let should_notify = message.priority;
        messages.push(message);
        drop(messages);
        if should_notify {
            self.notify.notify_one();
        }
    }

    /// Remove and return all pending steers.
    pub fn drain(&self) -> Vec<SteerMessage> {
        let mut messages = self.messages.lock().unwrap_or_else(|e| e.into_inner());
        self.priority.store(false, Ordering::SeqCst);
        std::mem::take(&mut *messages)
    }

    pub fn has_pending(&self) -> bool {
        !self.messages.lock().unwrap_or_else(|e| e.into_inner()).is_empty()
    }

    /// Wait until at least one steer is marked priority. The priority flag is
    /// checked before waiting, so a notification between polling iterations
    /// cannot be lost.
    pub async fn wait_priority(&self) {
        loop {
            if self.priority.load(Ordering::SeqCst) {
                return;
            }
            self.notify.notified().await;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn upserts_and_drains_steers() {
        let queue = SteerQueue::new();
        queue.push(SteerMessage {
            id: "a".into(),
            text: "first".into(),
            attachments: Vec::new(),
            priority: false,
        });
        queue.push(SteerMessage {
            id: "a".into(),
            text: "updated".into(),
            attachments: Vec::new(),
            priority: true,
        });
        assert!(queue.has_pending());
        let drained = queue.drain();
        assert_eq!(drained.len(), 1);
        assert_eq!(drained[0].text, "updated");
        assert!(drained[0].priority);
        assert!(!queue.has_pending());
    }
}

