/// Telegram Bot API rejects messages longer than 4096 UTF-16 code units.
const TELEGRAM_MAX_MESSAGE: usize = 4000;
/// Bot API `getFile` only serves files up to 20 MB.
const MAX_DOWNLOAD_BYTES: usize = 20 * 1024 * 1024;

#[derive(Clone)]
pub struct TelegramRelay {
    client: Client,
    token: Option<String>,
    is_online: Arc<AtomicBool>,
    allowed_users: Vec<String>,
    sessions: Arc<Mutex<HashMap<String, String>>>,
}

fn value_to_id(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        other => other.to_string(),
    }
}

fn split_message(text: &str, max: usize) -> Vec<String> {
    if text.len() <= max {
        return vec![text.to_string()];
    }
    let mut chunks = Vec::new();
    let mut current = String::new();
    for line in text.split_inclusive('\n') {
        if current.len() + line.len() > max && !current.is_empty() {
            chunks.push(std::mem::take(&mut current));
        }
        if line.len() > max {
            let mut rest = line;
            while rest.len() > max {
                let mut cut = max;
                while cut > 0 && !rest.is_char_boundary(cut) {
                    cut -= 1;
                }
                chunks.push(rest[..cut].to_string());
                rest = &rest[cut..];
            }
            current.push_str(rest);
        } else {
            current.push_str(line);
        }
    }
    if !current.is_empty() {
        chunks.push(current);
    }
    chunks
}

fn looks_like_text_file(name: &str, mime: &str) -> bool {
    if mime.starts_with("text/") || mime == "application/json" || mime == "application/xml" {
        return true;
    }
    let lower = name.to_lowercase();
    [
        ".txt", ".md", ".json", ".csv", ".yaml", ".yml", ".toml", ".ini", ".py", ".rs", ".ts",
        ".tsx", ".js", ".html", ".css", ".sh", ".ps1", ".sql", ".go", ".java",
    ]
    .iter()
    .any(|ext| lower.ends_with(ext))
}

/// Remove any URL from a message.
///
/// Telegram request URLs embed the bot token (`/bot<id>:<secret>/`), so a raw
/// transport error logged verbatim would leak the credential into logs and the
/// UI. Keeping the surrounding text preserves the diagnostic value.
fn scrub_urls(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(pos) = rest.find("http") {
        let (head, tail) = rest.split_at(pos);
        out.push_str(head);
        let end = tail
            .find(|c: char| c.is_whitespace() || c == ')' || c == '"' || c == '\'')
            .unwrap_or(tail.len());
        out.push_str("<url>");
        rest = &tail[end..];
    }
    out.push_str(rest);
    out
}

impl TelegramRelay {
    pub fn new(token: Option<String>) -> Self {
        let allowed_users = std::env::var("TELEGRAM_ALLOWED_USERS")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|item| item.trim().trim_start_matches('@').to_lowercase())
                    .filter(|item| !item.is_empty())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        Self::with_allowlist(token, allowed_users)
    }

    pub fn with_allowlist(token: Option<String>, allowed_users: Vec<String>) -> Self {
        let allowed_users = allowed_users
            .into_iter()
            .map(|item| item.trim().trim_start_matches('@').to_lowercase())
            .filter(|item| !item.is_empty())
            .collect::<Vec<_>>();
        let client = Client::builder()
            .connect_timeout(std::time::Duration::from_secs(20))
            // Long polling keeps the request open for `timeout` seconds.
            .timeout(std::time::Duration::from_secs(60))
            .build()
            .unwrap_or_else(|_| Client::new());
        Self {
            client,
            token,
            is_online: Arc::new(AtomicBool::new(false)),
            allowed_users,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn online_flag(&self) -> Arc<AtomicBool> {
        self.is_online.clone()
    }

    pub fn is_connected(&self) -> bool {
        self.is_online.load(Ordering::SeqCst)
    }

pub fn stop(&self) {
    self.is_online.store(false, Ordering::SeqCst);
}

async fn api_post(&self, method: &str, body: Value) -> Result<Value> {
    let token = self
        .token
        .as_ref()
        .ok_or_else(|| OdonError::Channel("Telegram bot token not configured".to_string()))?;
    let url = format!("https://api.telegram.org/bot{}/{}", token, method);
    let resp = self
        .client
        .post(&url)
        .json(&body)
        .send()
        .await
        .map_err(|e| OdonError::Channel(format!("Telegram {method} failed: {}", e.without_url())))?;
    let status = resp.status();
    let text = resp
        .text()
        .await
        .map_err(|e| OdonError::Channel(format!("Telegram {method} read failed: {}", e.without_url())))?;
    let val: Value = serde_json::from_str(&text).map_err(|e| {
        OdonError::Channel(format!(
            "Telegram {method} returned invalid JSON: {e}: {text}"
        ))
    })?;
    if !status.is_success() {
        return Err(OdonError::Channel(format!(
            "Telegram {method} HTTP {}: {}",
            status.as_u16(),
            val.get("description")
                .and_then(|d| d.as_str())
                .unwrap_or(&text)
        )));
    }
    Ok(val)
}

fn is_allowed(&self, message: &Value) -> bool {
    if self.allowed_users.is_empty() {
        // Secure default: without an allowlist the bot is not open to the
        // world. Operators must opt in explicitly.
        return std::env::var("TELEGRAM_ALLOW_ANYONE")
            .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
            .unwrap_or(false);
    }
    let from = message.get("from");
    let id = from
        .and_then(|f| f.get("id"))
        .map(value_to_id)
        .unwrap_or_default();
    let username = from
        .and_then(|f| f.get("username"))
        .and_then(|u| u.as_str())
        .unwrap_or("")
        .to_lowercase();
    self.allowed_users
        .iter()
        .any(|allowed| allowed == &id || allowed == &username)
}

async fn send_chat_action(&self, chat_id: &str, action: &str) {
    let _ = self
        .api_post(
            "sendChatAction",
            json!({ "chat_id": chat_id, "action": action }),
        )
        .await;
}

/// Send Markdown when the model output happens to be valid Telegram
/// Markdown, but always fall back to plain text so a parse error never
/// swallows the reply.

async fn send_text(&self, chat_id: &str, text: &str) -> Result<()> {
    for chunk in split_message(text, TELEGRAM_MAX_MESSAGE) {
        let with_markdown = json!({
            "chat_id": chat_id,
            "text": chunk,
            "parse_mode": "Markdown",
            "disable_web_page_preview": true,
        });
        let mut delivered = false;
        if let Ok(val) = self.api_post("sendMessage", with_markdown).await {
            delivered = val.get("ok").and_then(|o| o.as_bool()).unwrap_or(false);
        }
        if !delivered {
            let plain = json!({
                "chat_id": chat_id,
                "text": chunk,
                "disable_web_page_preview": true,
            });
            self.api_post("sendMessage", plain).await?;
        }
    }
    Ok(())
}

async fn send_document(
    &self,
    chat_id: &str,
    file_name: &str,
    mime_type: &str,
    bytes: Vec<u8>,
    caption: Option<&str>,
) -> Result<()> {
    let part = reqwest::multipart::Part::bytes(bytes)
        .file_name(file_name.to_string())
        .mime_str(mime_type)
        .map_err(|e| OdonError::Channel(format!("Invalid Telegram document MIME: {e}")))?;
    let mut form = reqwest::multipart::Form::new().text("chat_id", chat_id.to_string());
    if let Some(caption) = caption.filter(|value| !value.trim().is_empty()) {
        form = form.text("caption", caption.chars().take(900).collect::<String>());
    }
    form = form.part("document", part);
    let resp = self
        .client
        .post(format!(
            "https://api.telegram.org/bot{}/sendDocument",
            self.token.as_ref().ok_or_else(|| OdonError::Channel(
                "Telegram bot token not configured".to_string()
            ))?
        ))
        .multipart(form)
        .send()
        .await
        .map_err(|e| OdonError::Channel(format!("Telegram sendDocument failed: {e}")))?;
    let status = resp.status();
    let body = resp.text().await.unwrap_or_default();
    if !status.is_success() {
        return Err(OdonError::Channel(format!(
            "Telegram sendDocument HTTP {}: {body}",
            status.as_u16()
        )));
    }
    Ok(())
}

async fn send_photo(
    &self,
    chat_id: &str,
    file_name: &str,
    mime_type: &str,
    bytes: Vec<u8>,
    caption: Option<&str>,
) -> Result<()> {
    let part = reqwest::multipart::Part::bytes(bytes)
        .file_name(file_name.to_string())
