    Code,
    Document,
    Image,
    Patch,
    Automation,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Artifact {
    pub id: String,
    pub session_id: String,
    pub title: String,
    pub kind: ArtifactKind,
