    ) -> Self {
        Self {
            id: Uuid::new_v4().to_string(),
            session_id: session_id.into(),
            title: title.into(),
            kind: ArtifactKind::Patch,
            summary: format!(
                "+{} -{} lines ({} files)",
                additions, deletions, files_changed
