    .await?;
    token.plan = Some("Antigravity".to_string());

                Ok(token)
            }
        }
    }

    pub async fn refresh_for(&self, provider: &str, refresh_token: &str) -> Result<OAuthToken> {
        self.refresh(provider.parse()?, refresh_token).await
    }
