pub fn set_todos(&self, session_id: &str, items: &serde_json::Value) -> Result<()> {
    let conn = self.lock_conn()?;
    conn.execute(
        "INSERT INTO todos (session_id, items_json, updated_at) VALUES (?1, ?2, ?3)
         ON CONFLICT(session_id) DO UPDATE SET
