        })?;
        for r in rows {
            memories.push(r?);
        }
    } else {
        let mut stmt = conn.prepare(
            "SELECT key, value, category, updated_at FROM memories ORDER BY updated_at DESC",
        )?;
        let rows = stmt.query_map([], |row| {
            let updated_at_str: String = row.get(3)?;
