/// Real image generation. Calls an image model (OpenAI `gpt-image-1` or Google
/// Gemini image preview), writes the PNG into `<workspace>/generated/images/`
/// and returns an image artifact whose preview URL is served by the daemon.
/// If no image-capable key is configured it fails loudly instead of faking output.
pub struct ArtifactCreateChartTool;

#[async_trait]
impl Tool for ArtifactCreateChartTool {
    fn name(&self) -> &str {
        "artifact_create_chart"
    }
    fn description(&self) -> &str {
        "Create a bar or line chart artifact rendered as SVG in the chat and browser preview"
    }

fn parameters_schema(&self) -> Value {
    json!({
        "type": "object",
        "properties": {
            "title": { "type": "string", "description": "Chart title" },
            "chart_type": { "type": "string", "enum": ["bar", "line"], "description": "Chart type" },
            "labels": {
                "type": "array",
                "items": { "type": "string" },
                "description": "X-axis labels"
            },
            "values": {
                "type": "array",
                "items": { "type": "number" },
                "description": "Values for a single series"
            },
            "series": {
                "type": "array",
                "description": "Optional multiple series. Use instead of values.",
                "items": {
                    "type": "object",
                    "properties": {
                        "name": { "type": "string" },
                        "values": { "type": "array", "items": { "type": "number" } }
                    },
                    "required": ["values"]
                }
            }
        },
        "required": ["title", "chart_type", "labels"]
    })
}
fn risk_tier(&self) -> RiskTier {
    RiskTier::Tier1WorkspaceMutating
}
async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
    let title = args
        .get("title")
        .and_then(|t| t.as_str())
        .unwrap_or("Chart");
    let chart_type = args
        .get("chart_type")
        .and_then(|t| t.as_str())
        .unwrap_or("bar");
    if chart_type != "bar" && chart_type != "line" {
        return Err(OdonError::Tool {
            tool: self.name().to_string(),
            message: "chart_type must be 'bar' or 'line'".to_string(),
        });
    }
    let labels: Vec<String> = args
        .get("labels")
        .and_then(|l| l.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    if labels.is_empty() {
        return Err(OdonError::Tool {
            tool: self.name().to_string(),
            message: "labels must contain at least one entry".to_string(),
        });
    }

        let mut spec = json!({
            "type": chart_type,
            "title": title,
            "labels": labels,
        });
        if let Some(series) = args.get("series").and_then(|s| s.as_array()) {
            if !series.is_empty() {
                spec["series"] = Value::Array(series.clone());
            }
        }
        if spec.get("series").is_none() {
            let values = args
                .get("values")
                .and_then(|v| v.as_array())
                .cloned()
                .unwrap_or_default();
            if values.len() != labels.len() {
                return Err(OdonError::Tool {
                    tool: self.name().to_string(),
                    message: format!(
                        "values ({}) must match labels ({})",
                        values.len(),
                        labels.len()
                    ),
                });
            }
            spec["values"] = Value::Array(values);
        }

        let markdown = format!("## {}\n\n```chart\n{}\n```\n", title, spec);
        let artifact = Artifact::new_document(&ctx.session_id, title, "Chart", &markdown);

        Ok(json!({
            "artifact_id": artifact.id,
            "title": artifact.title,
            "kind": "document",
            "summary": artifact.summary,
            "artifact": artifact,
        }))
    }
}

pub struct ArtifactCreateImageTool;

struct ImageBackend {
    kind: &'static str, // "openai" | "google"
    key: String,
    base_url: String,
}

fn pick_backend(ctx: &ToolContext, want: Option<&str>) -> Option<ImageBackend> {
    let stored = |id: &str| {
        ctx.storage
            .as_ref()
            .and_then(|s| s.get_provider_config(id).ok().flatten())
    };
    let env = |n: &str| std::env::var(n).ok().filter(|v| !v.trim().is_empty());
    let openai = || {
        let (key, base) = match stored("openai") {
            Some(c) if !c.api_key.is_empty() => (c.api_key, c.base_url),
            _ => (env("OPENAI_API_KEY")?, env("OPENAI_BASE_URL")),
        };
        Some(ImageBackend {
            kind: "openai",
            key,
            base_url: base.unwrap_or_else(|| "https://api.openai.com/v1".into()),
        })
    };
    let google = || {
        let key = match stored("google") {
            Some(c) if !c.api_key.is_empty() => c.api_key,
            _ => env("GEMINI_API_KEY").or_else(|| env("GOOGLE_API_KEY"))?,
        };
        Some(ImageBackend {
            kind: "google",
            key,
            base_url: "https://generativelanguage.googleapis.com/v1beta".into(),
        })
    };

    match want {
        Some("google") | Some("gemini") => google(),
        Some("openai") => openai(),
        _ => openai().or_else(google),
    }
}

fn slugify(s: &str) -> String {
    let base: String = s
        .trim_end_matches(".png")
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect();
    let base = base.trim_matches('-');
    let base = if base.is_empty() { "image" } else { base };
    base.chars().take(48).collect()
}

fn png_dimensions(bytes: &[u8]) -> Option<(u32, u32)> {
    if bytes.len() > 24 && &bytes[0..8] == b"\x89PNG\r\n\x1a\n" {
        let w = u32::from_be_bytes(bytes[16..20].try_into().ok()?);
        let h = u32::from_be_bytes(bytes[20..24].try_into().ok()?);
        return Some((w, h));
    }
    None
}

#[async_trait]
impl Tool for ArtifactCreateImageTool {
    fn name(&self) -> &str {
        "artifact_create_image"
    }
    fn description(&self) -> &str {
        "Generate a real image from a text prompt with an image model and save it as a PNG file in the workspace (generated/images/). Returns an image artifact the user can view and download."
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "title": { "type": "string", "description": "Image title / file name (e.g. hero-illustration)" },
                "prompt": { "type": "string", "description": "Detailed image generation prompt" },
                "size": { "type": "string", "description": "OpenAI size: 1024x1024, 1536x1024 or 1024x1536 (default 1024x1024)" },
                "provider": { "type": "string", "description": "Optional: 'openai' or 'google'. Defaults to whichever is configured." }
            },
            "required": ["title", "prompt"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier1WorkspaceMutating
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        use base64::Engine;
        let tool_err = |m: String| OdonError::Tool {
            tool: "artifact_create_image".into(),
            message: m,
        };

        let title = args
            .get("title")
            .and_then(|t| t.as_str())
            .unwrap_or("image");
        let prompt = args
            .get("prompt")
            .and_then(|p| p.as_str())
            .filter(|p| !p.trim().is_empty())
            .ok_or_else(|| tool_err("'prompt' is required".into()))?;
        let size = args
            .get("size")
            .and_then(|s| s.as_str())
            .unwrap_or("1024x1024");
        let want = args.get("provider").and_then(|p| p.as_str());

        let backend = pick_backend(ctx, want);

let (bytes, model): (Vec<u8>, String) = match backend {
    Some(backend) => {
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(180))
            .build()
            .map_err(|e| tool_err(e.to_string()))?;

        if backend.kind == "openai" {
            let model = "gpt-image-1";
            let resp = client
                .post(format!(
                    "{}/images/generations",
                    backend.base_url.trim_end_matches('/')
                ))
                .bearer_auth(&backend.key)
                .json(&json!({ "model": model, "prompt": prompt, "size": size, "n": 1 }))
                .send()
                .await
                .map_err(|e| tool_err(format!("Image request failed: {e}")))?;
            let status = resp.status();
            let v: Value = resp.json().await.map_err(|e| tool_err(e.to_string()))?;
            if !status.is_success() {
                return Err(tool_err(format!("Image API error {status}: {v}")));
            }
            let item = v
                .pointer("/data/0")
                .ok_or_else(|| tool_err("Image API returned no data".into()))?;
            if let Some(b64) = item.get("b64_json").and_then(|b| b.as_str()) {
                (
                    base64::engine::general_purpose::STANDARD
                        .decode(b64)
                        .map_err(|e| tool_err(e.to_string()))?,
                    model.into(),
                )
            } else if let Some(url) = item.get("url").and_then(|u| u.as_str()) {
                let b = client
                    .get(url)
                    .send()
                    .await
                    .map_err(|e| tool_err(e.to_string()))?
                    .bytes()
                    .await
                    .map_err(|e| tool_err(e.to_string()))?;
                (b.to_vec(), model.into())
            } else {
                return Err(tool_err(
                    "Image API response had neither b64_json nor url".into(),
                ));
            }
        } else {
            let model = "gemini-2.5-flash-image";
            let resp = client
                .post(format!(
                    "{}/models/{}:generateContent",
                    backend.base_url, model
                ))
                .header("x-goog-api-key", &backend.key)
                .json(&json!({
                    "contents": [{ "parts": [{ "text": prompt }] }],
                    "generationConfig": { "responseModalities": ["IMAGE", "TEXT"] }
                }))
                .send()
                .await
                .map_err(|e| tool_err(format!("Image request failed: {e}")))?;
            let status = resp.status();
            let v: Value = resp.json().await.map_err(|e| tool_err(e.to_string()))?;
            if !status.is_success() {
                return Err(tool_err(format!("Gemini image API error {status}: {v}")));
            }
            let b64 = v
                .pointer("/candidates/0/content/parts")
                .and_then(|p| p.as_array())
                .and_then(|parts| {
                    parts.iter().find_map(|p| {
                        p.get("inlineData")
                            .or_else(|| p.get("inline_data"))
                            .and_then(|d| d.get("data"))
                            .and_then(|d| d.as_str())
                    })

                        })
                        .ok_or_else(|| tool_err(format!("Gemini returned no image: {v}")))?;
                    (
                        base64::engine::general_purpose::STANDARD
                            .decode(b64)
                            .map_err(|e| tool_err(e.to_string()))?,
                        model.into(),
                    )
                }
            }
            None => {
                return Err(tool_err(
                    "No image generation provider is configured. Add an OpenAI or Google Gemini API key in Settings, or set OPENAI_API_KEY / GEMINI_API_KEY.".into(),
                ));
            }
        };

        let (width, height) = png_dimensions(&bytes).unwrap_or((1024, 1024));
        let rel = format!(
            "generated/images/{}-{}.png",
            slugify(title),
            &uuid::Uuid::new_v4().simple().to_string()[..8]
        );
        let abs = crate::workspace_path::resolve_write(&ctx.workspace_root, &rel)?;
        if let Some(dir) = abs.parent() {
            std::fs::create_dir_all(dir)
                .map_err(|e| tool_err(format!("Cannot create {}: {e}", dir.display())))?;
        }
        std::fs::write(&abs, &bytes).map_err(|e| tool_err(format!("Cannot save image: {e}")))?;

        let artifact = Artifact::new_image(
            &ctx.session_id,
            title,
            prompt,
            width,
            height,
            model,
            Some(abs.to_string_lossy().to_string()),
            Some(format!("/api/files/{rel}")),
            bytes.len(),
        );

        Ok(json!({
            "artifact_id": artifact.id,
            "title": artifact.title,
            "kind": "image",
            "saved_to": abs.to_string_lossy(),
            "relative_path": rel,
            "summary": artifact.summary,
            "artifact": artifact,
        }))
    }
}

pub struct ArtifactUpdateTool;

#[async_trait]
impl Tool for ArtifactUpdateTool {
    fn name(&self) -> &str {
        "artifact_update"
    }
    fn description(&self) -> &str {
        "Update the content or metadata of an existing artifact"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "artifact_id": { "type": "string", "description": "ID of artifact to update" },
                "content": { "type": "string", "description": "New artifact content" }
            },
            "required": ["artifact_id", "content"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier1WorkspaceMutating
    }

    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let artifact_id = args
            .get("artifact_id")
            .and_then(|a| a.as_str())
            .unwrap_or("");
        let content = args.get("content").and_then(|c| c.as_str()).unwrap_or("");

        if let Some(storage) = &ctx.storage {
            if let Ok(mut art) = storage.get_artifact(artifact_id) {
                art.summary = format!("Updated: {}", content.chars().take(60).collect::<String>());
                match &mut art.payload {
                    odon_core::ArtifactPayload::Document {
                        markdown,
                        size_bytes,
                        ..
                    } => {
                        *markdown = content.to_string();
                        *size_bytes = content.len();
                    }
                    odon_core::ArtifactPayload::Code { files, .. } => {
                        if let Some(first) = files.first_mut() {
                            first.content = content.to_string();
                        }
                    }
                    odon_core::ArtifactPayload::Patch { diff, .. } => {
                        *diff = content.to_string();
                    }
                    _ => {}
                }
                let _ = storage.save_artifact(&art);
                return Ok(
                    json!({ "updated": true, "artifact_id": artifact_id, "size_bytes": content.len() }),
                );
            }
        }

        Ok(json!({ "updated": false, "artifact_id": artifact_id }))
    }
}

pub struct ArtifactImportTool;

#[async_trait]
impl Tool for ArtifactImportTool {
    fn name(&self) -> &str {
        "artifact_import"
    }
    fn description(&self) -> &str {
        "Import an existing file from workspace/disk into persistent artifacts storage"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "path": { "type": "string", "description": "Workspace-relative path of file to import" },
                "title": { "type": "string", "description": "Optional custom artifact title" },
                "summary": { "type": "string", "description": "Optional brief summary" }
            },
            "required": ["path"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let path_str = args.get("path").and_then(|p| p.as_str()).unwrap_or("");
        if path_str.is_empty() {
            return Err(OdonError::Tool {
                tool: self.name().to_string(),
                message: "Path is required".into(),
            });
        }

        let abs = crate::workspace_path::resolve_existing(&ctx.workspace_root, path_str)?;

if !abs.exists() {
    return Err(OdonError::Tool {
        tool: self.name().to_string(),
        message: format!("File not found: {}", abs.display()),
    });
}

let bytes = std::fs::read(&abs).map_err(|e| OdonError::Tool {
    tool: self.name().to_string(),
    message: format!("Failed to read file: {e}"),
})?;

let file_name = abs
    .file_name()
    .unwrap_or_default()
    .to_string_lossy()
    .to_string();
let ext = abs
    .extension()
    .map(|e| e.to_string_lossy().to_lowercase())
    .unwrap_or_default();
let title = args
    .get("title")
    .and_then(|t| t.as_str())
    .map(String::from)
    .unwrap_or_else(|| file_name.clone());
let summary = args
    .get("summary")
    .and_then(|s| s.as_str())
    .map(String::from)
    .unwrap_or_else(|| format!("Imported from {}", path_str));

let artifact = match ext.as_str() {
    "rs" | "ts" | "tsx" | "js" | "jsx" | "py" | "go" | "html" | "css" | "json" | "sh"
    | "yaml" | "yml" | "toml" => {
        let code_text = String::from_utf8_lossy(&bytes).to_string();
        let lang = match ext.as_str() {
            "rs" => "rust",
            "ts" | "tsx" => "typescript",
            "js" | "jsx" => "javascript",
            "py" => "python",
            "go" => "go",
            "html" => "html",
            "css" => "css",
            "json" => "json",
            "sh" => "bash",
            _ => "plaintext",
        };
        Artifact::new_code(
            &ctx.session_id,
            &title,
            &summary,
            lang,
            None,
            vec![odon_core::ArtifactFile {
                path: file_name.clone(),
                content: code_text,
            }],
        )
    }
    "png" | "jpg" | "jpeg" | "webp" | "gif" => Artifact::new_image(
        &ctx.session_id,
        &title,
        &summary,
        1024,
        1024,
        "imported",
        Some(abs.to_string_lossy().to_string()),
        Some(format!("/api/files/{}", path_str.replace('\\', "/"))),
        bytes.len(),
    ),
    _ => {
        let doc_text = String::from_utf8_lossy(&bytes).to_string();
        let doc_type = if ext == "md" { "markdown" } else { "text" };
        Artifact::new_document(&ctx.session_id, &title, doc_type, &doc_text)
    }
};

        if let Some(storage) = &ctx.storage {
            storage
                .save_artifact(&artifact)
                .map_err(|e| OdonError::Tool {
                    tool: self.name().to_string(),
                    message: format!("Failed to save artifact to storage: {e}"),
                })?;
        }

        Ok(json!({
            "imported": true,
            "artifact_id": artifact.id,
            "title": artifact.title,
            "kind": artifact.kind,
            "size_bytes": bytes.len(),
            "path": path_str
        }))
    }
}

// Daemon-facing bridge over the persistent browser sessions.
//
// The desktop panel and the agent tools must drive the same Chromium instance,
// otherwise the panel is decoration: the agent would click in a browser nobody
// can see and the user would drive a second, disconnected one. Every function
// here operates on the store in `browser_session`, so both sides share it.

use crate::browser_session::{
    browser, cdp, create_session, err, evaluate_js, find_persisted_meta, live,
    load_persisted_sessions, save_meta, validate_session_id,
};
use odon_core::error::Result;
use serde_json::{json, Value};

/// One row per known session, live or merely persisted on disk.
pub async fn list_sessions(workspace_root: &str) -> Result<Value> {
    load_persisted_sessions(workspace_root).await;
    let live_map = live().lock().await;
    let mut sessions: Vec<Value> = Vec::new();
    for (id, handle) in live_map.iter() {
        let live = handle.lock().await;
        sessions.push(json!({
            "session_id": id,
            "url": live.meta.url,
            "port": live.meta.port,
            "pid": live.meta.pid,
            "created_at": live.meta.created_at,
            "live": true
        }));
    }
    sessions.sort_by(|a, b| {
        b["created_at"]
            .as_str()
            .unwrap_or("")
            .cmp(a["created_at"].as_str().unwrap_or(""))
    });
    Ok(json!({ "sessions": sessions, "browser": browser().is_ok() }))
}

/// Create a session for the panel and return its metadata.
pub async fn open_session(workspace_root: &str, url: &str) -> Result<Value> {
    let url = if url.trim().is_empty() {
        "about:blank"
    } else {
        url.trim()
    };
    if !url.starts_with("about:") {
        crate::net_guard::validate_url_allow_loopback(url).await?;
    }
    let meta = create_session(workspace_root, url).await?;
    Ok(json!({
        "session_id": meta.session_id,
        "url": meta.url,
        "created_at": meta.created_at,
        "live": true
    }))
}

async fn require_live(id: &str) -> Result<()> {
    let known = live().lock().await.contains_key(id);
    if known {
        Ok(())
    } else {
        Err(err(format!(
            "session '{id}' is not live; resume or create one first"
        )))
    }
}

/// Navigate an existing session and wait for the document to settle.
pub async fn navigate(workspace_root: &str, id: &str, url: &str, timeout_ms: u64) -> Result<Value> {
    let id = validate_session_id(id)?;
    crate::net_guard::validate_url_allow_loopback(url).await?;
    require_live(id).await?;
    cdp(id, "Page.navigate", json!({ "url": url })).await?;
    let started = std::time::Instant::now();
    let timeout_ms = timeout_ms.clamp(1_000, 30_000);
    let mut ready = false;
    while started.elapsed().as_millis() < timeout_ms as u128 {
        let state = evaluate_js(id, "document.readyState").await?;
        if state.get("value").and_then(Value::as_str) == Some("complete") {
            ready = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    }
    let current = evaluate_js(id, "location.href").await?;
    let title = evaluate_js(id, "document.title").await?;
    let final_url = current
        .get("value")
        .and_then(Value::as_str)
        .unwrap_or(url)
        .to_string();
    touch(workspace_root, id, &final_url).await;
    Ok(json!({
        "session_id": id,
        "url": final_url,
        "title": title.get("value").and_then(Value::as_str).unwrap_or(""),
        "ready": ready
    }))
}

/// Keep the persisted URL in sync so a resumed session reopens where it was.
async fn touch(workspace_root: &str, id: &str, url: &str) {
    let mut map = live().lock().await;
    if let Some(handle) = map.get_mut(id) {
        let mut guard = handle.lock().await;
        guard.meta.url = url.to_string();
        guard.meta.last_used_at = chrono::Utc::now().to_rfc3339();
        let meta = guard.meta.clone();
        drop(guard);
        let _ = save_meta(workspace_root, &meta);
    }
}

/// Visible page state: url, title, text and links the agent can reason about.
pub async fn page_state(id: &str) -> Result<Value> {
    let id = validate_session_id(id)?;
    require_live(id).await?;
    let url = evaluate_js(id, "location.href").await?;
    let title = evaluate_js(id, "document.title").await?;
    let text = evaluate_js(id, "document.body ? document.body.innerText.slice(0, 20000) : ''").await?;
    let links = evaluate_js(
        id,
        "(Array.from(document.querySelectorAll('a[href]')).slice(0,200).map(a=>a.href))",
    )
    .await?;
    Ok(json!({
        "session_id": id,
        "url": url.get("value").and_then(Value::as_str).unwrap_or(""),
        "title": title.get("value").and_then(Value::as_str).unwrap_or(""),
        "text": text.get("value").and_then(Value::as_str).unwrap_or(""),
        "links": links.get("value").cloned().unwrap_or(Value::Array(vec![]))
    }))
}

/// Base64 PNG of the current viewport, for the panel's live view.
pub async fn screenshot(id: &str) -> Result<String> {
    let id = validate_session_id(id)?;
    require_live(id).await?;
    let shot = cdp(
        id,
        "Page.captureScreenshot",
        json!({ "format": "png", "captureBeyondViewport": false }),
    )
    .await?;
    shot.pointer("/result/data")
        .and_then(Value::as_str)
        .map(|s| s.to_string())
        .ok_or_else(|| err("browser did not return a screenshot"))
}

/// Click at viewport coordinates (CSS pixels, not device pixels).
pub async fn click(id: &str, x: f64, y: f64) -> Result<()> {
    let id = validate_session_id(id)?;
    require_live(id).await?;
    for kind in ["mousePressed", "mouseReleased"] {
        cdp(
            id,
            "Input.dispatchMouseEvent",
            json!({
                "type": kind,
                "x": x,
                "y": y,
                "button": "left",
                "clickCount": 1
            }),
        )
        .await?;
    }
    Ok(())
}

/// Type text into whatever currently holds focus.
pub async fn type_text(id: &str, text: &str) -> Result<()> {
    let id = validate_session_id(id)?;
    require_live(id).await?;
    cdp(id, "Input.insertText", json!({ "text": text })).await?;
    Ok(())
}

/// Close a session and drop its process.
pub async fn close(id: &str) -> Result<()> {
    let id = validate_session_id(id)?;
    let handle = live().lock().await.remove(id);
    match handle {
        Some(h) => {
            let mut guard = h.lock().await;
            let _ = guard.child.kill().await;
            Ok(())
        }
        None => Ok(()),
    }
}

/// Persisted metadata for a session that is no longer live.
pub fn persisted_meta(workspace_root: &str, id: &str) -> Result<Value> {
    let id = validate_session_id(id)?;
    let meta = find_persisted_meta(workspace_root, id)?;
    Ok(json!({
        "session_id": meta.session_id,
        "url": meta.url,
        "created_at": meta.created_at,
        "live": false
    }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::browser_session::create_session;

fn workspace() -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!("odon-bridge-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// The panel and the agent must drive one browser, not two. `create_session`
/// is exactly what `browser_session_create` calls, so a session it makes
/// must be visible through the bridge the panel reads.
///
/// Opt-in: launching a real browser is slow and noisy, so it only runs with
/// `ODON_BROWSER_TEST=1` rather than on every `cargo test`.
#[tokio::test]
async fn bridge_lists_the_session_created_for_the_agent() {
    if std::env::var("ODON_BROWSER_TEST").ok().as_deref() != Some("1") || browser().is_err() {
        return; // Not requested, or no Chromium on this machine.
    }
    let root = workspace();
    let root_s = root.display().to_string();
    let meta = create_session(&root_s, "about:blank").await.unwrap();

    let listed = list_sessions(&root_s).await.unwrap();
    let ids: Vec<String> = listed["sessions"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|s| s["session_id"].as_str().map(str::to_string))
        .collect();
    assert!(
        ids.contains(&meta.session_id),
        "bridge did not expose the agent's session: {ids:?}"
    );

    // A real screenshot round-trip proves the bridge talks to the same CDP tab.
    let started = std::time::Instant::now();
    let mut png = String::new();
    while started.elapsed() < std::time::Duration::from_secs(8) {
        if let Ok(data) = screenshot(&meta.session_id).await {
            if !data.is_empty() {
                png = data;
                break;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(250)).await;
    }
    assert!(png.starts_with("iVBORw0KGgo"), "expected PNG data, got {} bytes", png.len());

    close(&meta.session_id).await.unwrap();
    let after = list_sessions(&root_s).await.unwrap();
    let still_live = after["sessions"]
        .as_array()
        .unwrap()
        .iter()
        .any(|s| s["session_id"].as_str() == Some(meta.session_id.as_str()));
    assert!(!still_live, "closed session still listed as live");
}

/// The panel shows a live frame, so a screenshot of a *rendered* page must
/// come back as a real PNG. An empty payload or a stalled CDP read would
/// leave the panel blank, which this proves cannot happen silently.
#[tokio::test]
async fn screenshot_of_a_rendered_page_is_a_png() {
    if std::env::var("ODON_BROWSER_TEST").ok().as_deref() != Some("1") || browser().is_err() {
        return;
    }
    let root = workspace();
    let root_s = root.display().to_string();
    let page = "data:text/html,<h1 style='font:48px sans-serif'>odon live</h1>";
    let meta = create_session(&root_s, page).await.unwrap();

        let started = std::time::Instant::now();
        let mut png = String::new();
        while started.elapsed() < std::time::Duration::from_secs(10) {
            if let Ok(data) = screenshot(&meta.session_id).await {
                if !data.is_empty() {
                    png = data;
                    break;
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        }
        assert!(
            png.starts_with("iVBORw0KGgo"),
            "expected PNG data, got {} bytes",
            png.len()
        );

        // The agent must also be able to read the same page it screenshots.
        let text = page_state(&meta.session_id).await.unwrap();
        assert!(
            text["text"].as_str().unwrap_or("").contains("odon live"),
            "agent could not read the rendered page: {text}"
        );

        close(&meta.session_id).await.unwrap();
    }

    /// Unknown ids must be rejected before any CDP call is attempted.
    #[tokio::test]
    async fn unknown_session_is_rejected() {
        let root = workspace();
        let err = screenshot("session_does_not_exist").await.unwrap_err();
        assert!(err.to_string().contains("not live"), "unexpected error: {err}");
        let bad = navigate(&root.display().to_string(), "../etc", "https://example.com", 5_000)
            .await
            .unwrap_err();
        assert!(bad.to_string().contains("session_id"), "unexpected error: {bad}");
    }
}

use crate::registry::{Tool, ToolContext};
use async_trait::async_trait;
use futures_util::{SinkExt, StreamExt};
use odon_core::error::{OdonError, Result};
use odon_security::RiskTier;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{
    collections::HashMap,
    path::{Path, PathBuf},
    sync::Arc,
    time::Duration,
};
use tokio::{
    process::{Child, Command},
    sync::Mutex,
};

// ── Data ────────────────────────────────────────────────────────────────────

#[derive(Clone, Serialize, Deserialize)]
pub(crate) struct Meta {
    pub(crate) session_id: String,
    pub(crate) profile_dir: String,
    pub(crate) port: u16,
    pub(crate) pid: u32,
    pub(crate) url: String,
    pub(crate) created_at: String,
    pub(crate) last_used_at: String,
}

pub(crate) struct Live {
    pub(crate) meta: Meta,
    pub(crate) child: Child,
}

// Live (running) sessions keyed by session_id.
type LiveStore = Arc<Mutex<HashMap<String, Arc<Mutex<Live>>>>>;
static LIVE: std::sync::OnceLock<LiveStore> = std::sync::OnceLock::new();
pub(crate) fn live() -> &'static LiveStore {
    LIVE.get_or_init(|| Arc::new(Mutex::new(HashMap::new())))
}

// Persisted (metadata-only, no running process) sessions keyed by session_id.
type PersistedStore = Arc<Mutex<HashMap<String, Meta>>>;
static PERSISTED: std::sync::OnceLock<PersistedStore> = std::sync::OnceLock::new();
pub(crate) fn persisted() -> &'static PersistedStore {
    PERSISTED.get_or_init(|| Arc::new(Mutex::new(HashMap::new())))
}

// ── Path helpers ────────────────────────────────────────────────────────────

const METADATA_FILE: &str = "session.json";

/// The root directory that holds all browser-session subdirectories.
pub(crate) fn sessions_dir(workspace_root: &str) -> PathBuf {
    Path::new(workspace_root).join(".odon/browser-sessions")
}

/// Directory for a single session: `<sessions_dir>/<session_id>`.
pub(crate) fn session_dir(workspace_root: &str, session_id: &str) -> PathBuf {
    sessions_dir(workspace_root).join(session_id)
}

// ── Persistence helpers ─────────────────────────────────────────────────────

/// Scan the sessions directory and load every readable `session.json` into the
/// in-memory persisted store.  Called once from `store_init()` so that
/// `browser_session_resume` and `browser_session_list` can discover sessions
/// from a previous process lifetime.
pub(crate) async fn load_persisted_sessions(workspace_root: &str) {
    let dir = sessions_dir(workspace_root);
    let mut entries = match std::fs::read_dir(&dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut map = HashMap::new();
    while let Some(Ok(entry)) = entries.next() {
        let path = entry.path().join(METADATA_FILE);
        if let Ok(bytes) = std::fs::read(&path) {
            if let Ok(meta) = serde_json::from_slice::<Meta>(&bytes) {
                map.insert(meta.session_id.clone(), meta);
            }
        }
    }
    *persisted().lock().await = map;
}

/// Persist a `Meta` record to `<session_dir>/session.json`.
pub(crate) fn save_meta(workspace_root: &str, meta: &Meta) -> Result<()> {
    let dir = session_dir(workspace_root, &meta.session_id);
    std::fs::create_dir_all(&dir).map_err(|e| err(e.to_string()))?;
    std::fs::write(
        dir.join(METADATA_FILE),
        serde_json::to_vec_pretty(meta).unwrap(),
    )
    .map_err(|e| err(e.to_string()))
}

/// Return the persisted `Meta` for `session_id` if present on disk, without
/// touching the in-memory stores.
pub(crate) fn find_persisted_meta(workspace_root: &str, session_id: &str) -> Result<Meta> {
    let path = session_dir(workspace_root, session_id).join(METADATA_FILE);
    let bytes = std::fs::read(&path).map_err(|_| err("session metadata not found"))?;
    serde_json::from_slice(&bytes).map_err(|e| err(e.to_string()))
}

// ── Utilities ───────────────────────────────────────────────────────────────

pub(crate) fn err(msg: impl Into<String>) -> OdonError {
    OdonError::Tool {
        tool: "browser_session".into(),
        message: msg.into(),
    }
}

pub(crate) fn sid() -> String {
    format!("session_{}", chrono::Utc::now().timestamp_millis())
}

pub(crate) fn validate_session_id(id: &str) -> Result<&str> {
    if id.is_empty()
        || id.len() > 96
        || !id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
    {
        return Err(err(
            "session_id must contain only ASCII letters, numbers, '_' or '-' and be at most 96 characters",
        ));
    }
    Ok(id)
}

pub(crate) fn browser() -> Result<PathBuf> {
    let mut p = Vec::new();
    if cfg!(windows) {
        for variable in ["PROGRAMFILES", "PROGRAMFILES(X86)"] {
            if let Ok(x) = std::env::var(variable) {
                p.push(PathBuf::from(x.clone()).join("Google/Chrome/Application/chrome.exe"));
                p.push(PathBuf::from(x).join("Microsoft/Edge/Application/msedge.exe"));
            }
        }
        if let Ok(x) = std::env::var("LOCALAPPDATA") {
            p.push(PathBuf::from(x.clone()).join("Google/Chrome/Application/chrome.exe"));
            p.push(PathBuf::from(x).join("Microsoft/Edge/Application/msedge.exe"));
        }
    } else {
        p.extend([
            PathBuf::from("/usr/bin/google-chrome"),
            PathBuf::from("/usr/bin/chromium"),
            PathBuf::from("/usr/bin/microsoft-edge"),
        ]);
    }
    p.into_iter()

        .find(|x| x.is_file())
        .ok_or_else(|| err("Chrome/Chromium/Edge executable not found"))
}

pub(crate) async fn port() -> Result<u16> {
    let l = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .map_err(|e| err(e.to_string()))?;
    Ok(l.local_addr().map_err(|e| err(e.to_string()))?.port())
}

pub(crate) async fn cdp(id: &str, method: &str, params: Value) -> Result<Value> {
    let live = live()
        .lock()
        .await
        .get(id)
        .cloned()
        .ok_or_else(|| err(format!("session '{id}' is not live; resume it first")))?;
    let p = live.lock().await.meta.port;
    // A session that was just spawned has not published its page target yet,
    // so wait briefly instead of failing the panel and the agent with
    // "no active browser tab" during startup.
    let deadline_target = tokio::time::Instant::now() + Duration::from_secs(10);
    let u = loop {
        let mut found = None;
        if let Ok(r) = reqwest::get(format!("http://127.0.0.1:{p}/json")).await {
            if let Ok(ts) = r.json::<Vec<Value>>().await {
                found = ts
                    .iter()
                    .filter(|x| {
                        x.get("type")
                            .and_then(Value::as_str)
                            .map(|t| t == "page")
                            .unwrap_or(true)
                    })
                    .find_map(|x| x.get("webSocketDebuggerUrl").and_then(Value::as_str))
                    .map(str::to_string);
            }
        }
        if let Some(found) = found {
            break found;
        }
        if tokio::time::Instant::now() >= deadline_target {
            return Err(err("no active browser tab"));
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    };
    let (mut ws, _) = tokio_tungstenite::connect_async(u)
        .await
        .map_err(|e| err(e.to_string()))?;
    ws.send(tokio_tungstenite::tungstenite::Message::Text(
        json!({ "id": 1, "method": method, "params": params })
            .to_string()
            .into(),
    ))
    .await
    .map_err(|e| err(e.to_string()))?;
    // CDP pushes unsolicited events on the same socket, so the first frame is
    // not necessarily our reply. Wait for the frame whose id matches ours and
    // surface Chrome's own error text instead of a generic fallback.
    let deadline = tokio::time::Instant::now() + Duration::from_secs(20);
    loop {
        let left = deadline.saturating_duration_since(tokio::time::Instant::now());
        if left.is_zero() {
            return Err(err(format!("CDP timeout waiting for {method}")));
        }
        let m = tokio::time::timeout(left, ws.next())
            .await
            .map_err(|_| err(format!("CDP timeout waiting for {method}")))?
            .ok_or_else(|| err("CDP closed"))?
            .map_err(|e| err(e.to_string()))?;
        let text = match m {
            tokio_tungstenite::tungstenite::Message::Text(x) => x,
            tokio_tungstenite::tungstenite::Message::Close(_) => {
                return Err(err("CDP closed"))
            }
            _ => continue,
        };
        let frame: Value = serde_json::from_str(&text).map_err(|e| err(e.to_string()))?;
        if frame.get("id").and_then(Value::as_i64) != Some(1) {

            continue;
        }
        if let Some(e) = frame.get("error") {
            let msg = e
                .get("message")
                .and_then(Value::as_str)
                .map(str::to_string)
                .unwrap_or_else(|| e.to_string());
            let data = e
                .get("data")
                .and_then(Value::as_str)
                .map(|d| format!(": {d}"))
                .unwrap_or_default();
            return Err(err(format!("{method} failed: {msg}{data}")));
        }
        return Ok(frame);
    }
}

pub(crate) fn schema(props: Value, req: Value) -> Value {
    json!({ "type": "object", "properties": props, "required": req })
}

pub(crate) async fn evaluate_js(id: &str, expression: &str) -> Result<Value> {
    let response = cdp(
        id,
        "Runtime.evaluate",
        json!({ "expression": expression, "returnByValue": true, "awaitPromise": false }),
    )
    .await?;
    if let Some(exception) = response.pointer("/result/exceptionDetails") {
        let text = exception
            .pointer("/exception/description")
            .or_else(|| exception.pointer("/text"))
            .and_then(Value::as_str)
            .unwrap_or("browser evaluation failed");
        return Err(err(text.to_string()));
    }
    Ok(response
        .pointer("/result/result")
        .cloned()
        .unwrap_or(Value::Null))
}

fn visible_expression(selector: &str) -> String {
    let encoded = serde_json::to_string(selector).unwrap_or_else(|_| "\"\"".to_string());
    format!(
        "(()=>{{const e=document.querySelector({encoded});if(!e)return false;const r=e.getBoundingClientRect();const style=getComputedStyle(e);return r.width>0&&r.height>0&&style.visibility!=='hidden'&&style.display!=='none'}})()",
        encoded = encoded
    )
}

async fn wait_visible(id: &str, selector: &str, timeout_ms: u64) -> Result<bool> {
    let expression = visible_expression(selector);
    let started = std::time::Instant::now();
    while started.elapsed().as_millis() < timeout_ms as u128 {
        let value = evaluate_js(id, &expression).await?;
        if value.get("value").and_then(Value::as_bool).unwrap_or(false) {
            return Ok(true);
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    }
    Ok(false)
}

