#[cfg(test)]
mod tests {
    use super::*;
    use odon_security::{ApprovalEngine, AuditLogger, SecurityPolicy};
    use std::sync::Arc;

    fn test_context(root: &str) -> crate::registry::ToolContext {
        crate::registry::ToolContext {
            session_id: "diff-test".to_string(),
            workspace_root: root.to_string(),
            approval_engine: Arc::new(ApprovalEngine::new(SecurityPolicy::default())),
            audit_logger: Arc::new(AuditLogger::new()),
            storage: None,
        }
    }

    #[test]
    fn rejects_absolute_and_parent_paths() {
        let root = std::env::temp_dir().join(format!("odon-fs-test-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        let root_str = root.to_string_lossy();

        assert!(resolve_path(&root_str, "../outside.txt").is_err());
        assert!(resolve_path(&root_str, &root.join("absolute.txt").to_string_lossy()).is_err());
        assert!(resolve_path(&root_str, "nested/file.txt").is_ok());

        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn edit_returns_patch_artifact_with_added_and_removed_lines() {
        let root = std::env::temp_dir().join(format!("odon-fs-diff-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("note.txt"), "alpha\nbeta\ngamma\n").unwrap();

        let ctx = test_context(&root.to_string_lossy());
        let out = FsEditTool
            .execute(
                &ctx,
                json!({
                    "path": "note.txt",
                    "target": "beta",
                    "replacement": "BETA\ninserted"
                }),
            )
            .await
            .expect("edit should succeed");

        let artifact = out.get("artifact").expect("artifact field");
        assert_eq!(artifact["kind"], "patch");
        let diff = artifact["payload"]["data"]["diff"]
            .as_str()
            .expect("diff text");
        assert!(diff.contains("-beta\n"), "removed line must be marked: {diff}");
        assert!(diff.contains("+BETA\n"), "added line must be marked: {diff}");
        assert_eq!(artifact["payload"]["data"]["additions"], 2);
        assert_eq!(artifact["payload"]["data"]["deletions"], 1);

        std::fs::remove_dir_all(root).unwrap();
    }
}

use async_trait::async_trait;
use odon_core::{OdonError, Result};
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::fs;
use std::path::{Component, Path, PathBuf};

use crate::registry::{Tool, ToolContext};

fn add_path_to_zip(
    zip: &mut zip::ZipWriter<std::fs::File>,
    base: &Path,
    path: &Path,
    options: zip::write::SimpleFileOptions,
) -> std::result::Result<(), String> {
    // Do not follow symlinks: a workspace symlink to ~/.ssh would otherwise
    // be archived verbatim into an in-workspace zip.
    let type_ = fs::symlink_metadata(path)
        .map_err(|e| e.to_string())?
        .file_type();
    if type_.is_dir() {
        let mut entries: Vec<_> = fs::read_dir(path)
            .map_err(|e| e.to_string())?
            .collect::<std::result::Result<Vec<_>, _>>()
            .map_err(|e| e.to_string())?;
        entries.sort_by_key(|entry| entry.path());
        for entry in entries {
            add_path_to_zip(zip, base, &entry.path(), options)?;
        }
    } else if type_.is_file() {
        let name = path
            .strip_prefix(base)
            .unwrap_or(path)
            .to_string_lossy()
            .replace('\\', "/");
        zip.start_file(name, options).map_err(|e| e.to_string())?;
        let mut file = fs::File::open(path).map_err(|e| e.to_string())?;
        std::io::copy(&mut file, zip).map_err(|e| e.to_string())?;
    }
    Ok(())
}

fn resolve_path(root: &str, relative: &str) -> Result<PathBuf> {
    let p = Path::new(relative);
    if p.is_absolute()
        || p.components().any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        return Err(OdonError::Tool {
            tool: "filesystem_ext".to_string(),
            message: format!("Path must stay inside the workspace: {relative}"),
        });
    }

    let canonical_root = fs::canonicalize(root).map_err(|e| OdonError::Tool {
        tool: "filesystem_ext".to_string(),
        message: format!("Failed to resolve workspace root: {e}"),
    })?;
    let candidate = canonical_root.join(p);

    let mut existing = candidate.as_path();
    while std::fs::symlink_metadata(existing).is_err() {
        existing = existing.parent().ok_or_else(|| OdonError::Tool {
            tool: "filesystem_ext".to_string(),
            message: format!("Invalid workspace path: {relative}"),
        })?;
    }
    let canonical_existing = fs::canonicalize(existing).map_err(|e| OdonError::Tool {
        tool: "filesystem_ext".to_string(),
        message: format!("Failed to resolve path {relative}: {e}"),
    })?;
    if !canonical_existing.starts_with(&canonical_root) {
        return Err(OdonError::Tool {
            tool: "filesystem_ext".to_string(),
            message: format!("Path escapes the workspace: {relative}"),
        });

    }

    Ok(candidate)
}

// 1. fs_stat
pub struct FsStatTool;
#[async_trait]
impl Tool for FsStatTool {
    fn name(&self) -> &str {
        "fs_stat"
    }
    fn description(&self) -> &str {
        "Get comprehensive metadata and statistics for a file or directory"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "path": { "type": "string", "description": "Relative file or directory path" }
            },
            "required": ["path"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let rel = args
            .get("path")
            .and_then(|p| p.as_str())
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: "Missing 'path' argument".to_string(),
            })?;
        let full = resolve_path(&ctx.workspace_root, rel)?;
        let meta = fs::metadata(&full).map_err(|e| OdonError::Tool {
            tool: self.name().to_string(),
            message: format!("Failed to read metadata for {rel}: {e}"),
        })?;

        let modified = meta.modified().ok().map(|t| {
            let dt: chrono::DateTime<chrono::Utc> = t.into();
            dt.to_rfc3339()
        });
        let created = meta.created().ok().map(|t| {
            let dt: chrono::DateTime<chrono::Utc> = t.into();
            dt.to_rfc3339()
        });

        Ok(json!({
            "path": rel,
            "is_dir": meta.is_dir(),
            "is_file": meta.is_file(),
            "is_symlink": meta.is_symlink(),
            "size_bytes": meta.len(),
            "readonly": meta.permissions().readonly(),
            "modified_at": modified,
            "created_at": created,
        }))
    }
}

