fn tool_error(name: &str, message: impl Into<String>) -> OdonError {
    OdonError::Tool {
        tool: name.to_string(),
        message: message.into(),
    }
}

async fn powershell(name: &str, script: &str, args: &[String]) -> Result<Value> {
    if !cfg!(windows) {
        return Err(tool_error(
            name,
            "local application control is currently implemented for Windows only",
        ));
    }
    let output = Command::new("powershell.exe")
        .args([
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            script,
            "--",
        ])
        .args(args)
        .output()
        .await
        .map_err(|e| tool_error(name, format!("failed to start PowerShell: {e}")))?;
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    if !output.status.success() {
        return Err(tool_error(
            name,
            if stderr.is_empty() { stdout } else { stderr },
        ));
    }
    serde_json::from_str(&stdout).map_err(|e| {
        tool_error(
            name,
            format!("PowerShell returned invalid JSON: {e}; output={stdout}"),
        )
    })
}

pub struct LocalAppListTool;
