        Ok(json!({
            "server_id": id,
            "name": name,
            "previous_enabled": previous,
            "enabled": enabled,
            "status": "updated"
        }))
    }
}

use crate::registry::{Tool, ToolContext};
use async_trait::async_trait;
use odon_core::error::{OdonError, Result};
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::path::{Path, PathBuf};

fn tool_error(name: &str, message: impl Into<String>) -> OdonError {
    OdonError::Tool {
        tool: name.to_string(),
        message: message.into(),
    }
}

fn file_path(ctx: &ToolContext, raw: &str, tool: &str) -> Result<PathBuf> {
    let path = Path::new(raw);
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        Path::new(&ctx.workspace_root).join(path)
    };
    let canonical = std::fs::canonicalize(&absolute)
        .map_err(|e| tool_error(tool, format!("cannot access media file: {e}")))?;
    let root = std::fs::canonicalize(&ctx.workspace_root)
        .map_err(|e| tool_error(tool, format!("cannot resolve workspace: {e}")))?;
    if !canonical.starts_with(&root) {
        return Err(tool_error(tool, "media file must be inside the workspace"));
    }
    if !canonical.is_file() {
        return Err(tool_error(tool, "media path is not a regular file"));
    }
    Ok(canonical)
}

async fn send_telegram(ctx: &ToolContext, tool: &str, args: Value, method: &str) -> Result<Value> {
    let token = std::env::var("TELEGRAM_BOT_TOKEN")
        .map_err(|_| tool_error(tool, "TELEGRAM_BOT_TOKEN is not configured"))?;
    let chat_id = args
        .get("chat_id")
        .and_then(Value::as_str)
        .ok_or_else(|| tool_error(tool, "chat_id is required"))?;
    let raw = args
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| tool_error(tool, "path is required"))?;
    let path = file_path(ctx, raw, tool)?;
    let bytes = tokio::fs::read(&path)
        .await
        .map_err(|e| tool_error(tool, format!("cannot read media file: {e}")))?;
    const MAX_TELEGRAM_MEDIA_BYTES: usize = 50 * 1024 * 1024;
    if bytes.len() > MAX_TELEGRAM_MEDIA_BYTES {
        return Err(tool_error(
            tool,
            format!(
                "media file is too large: {} bytes (Telegram limit is {} bytes)",
                bytes.len(),
                MAX_TELEGRAM_MEDIA_BYTES
            ),
        ));
    }
    let caption = args
        .get("caption")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let filename = path
        .file_name()
        .and_then(|x| x.to_str())
        .unwrap_or("media.bin")
        .to_string();
    let part_name = match method {
        "sendPhoto" => "photo",
        "sendAudio" => "audio",
        "sendVideo" => "video",
        _ => "document",
    };
    let mime = content_type(&filename).await?;
    let part = reqwest::multipart::Part::bytes(bytes)
        .file_name(filename.clone())
        .mime_str(mime)

        .map_err(|e| tool_error(tool, format!("invalid media content type: {e}")))?;
    let mut form = reqwest::multipart::Form::new()
        .text("chat_id", chat_id.to_string())
        .part(part_name, part);
    if let Some(caption) = caption {
        if caption.chars().count() > 1024 {
            return Err(tool_error(tool, "caption must be 1024 characters or fewer"));
        }
        form = form.text("caption", caption.to_string());
    }
    let url = format!("https://api.telegram.org/bot{token}/{method}");
    let response = reqwest::Client::new()
        .post(url)
        .multipart(form)
        .send()
        .await
        .map_err(|e| tool_error(tool, format!("Telegram request failed: {e}")))?;
    let status = response.status();
    let body: Value = response
        .json()
        .await
        .map_err(|e| tool_error(tool, format!("Telegram response was not JSON: {e}")))?;
    if !status.is_success() || body.get("ok") != Some(&Value::Bool(true)) {
        return Err(tool_error(tool, format!("Telegram rejected media: {body}")));
    }
    Ok(
        json!({"sent": true, "channel": "telegram", "method": method, "chat_id": chat_id, "path": path, "response": body}),
    )
}

async fn content_type(filename: &str) -> Result<&'static str> {
    let extension = Path::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())
        .unwrap_or_default();
    let content_type = match extension.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "mp3" => "audio/mpeg",
        "ogg" | "oga" => "audio/ogg",
        "wav" => "audio/wav",
        "m4a" => "audio/mp4",
        "mp4" => "video/mp4",
        "mov" => "video/quicktime",
        "webm" => "video/webm",
        "pdf" => "application/pdf",
        "txt" => "text/plain",
        "md" => "text/markdown",
        "json" => "application/json",
        "csv" => "text/csv",
        "zip" => "application/zip",
        _ => "application/octet-stream",
    };
    Ok(content_type)
}

