// 7. MCP Management Tools
pub struct McpAddServerTool;
#[async_trait]
impl Tool for McpAddServerTool {
    fn name(&self) -> &str {
        "mcp_add_server"
    }
    fn description(&self) -> &str {
        "Register a new external MCP server (stdio or sse)"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "id": { "type": "string" },
                "name": { "type": "string" },
                "transport": { "type": "string", "enum": ["stdio", "sse"] },
                "command": { "type": "string" },
                "args": { "type": "array", "items": { "type": "string" } },
                "url": { "type": "string" },
                "env": { "type": "object", "description": "Environment variables passed to a stdio MCP server", "additionalProperties": { "type": "string" } }
            },
            "required": ["id", "name", "transport"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        // stdio MCP servers spawn an arbitrary local command on every call;
        // treat registration as system-mutating rather than workspace-mutating.
        RiskTier::Tier2SystemMutating
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let id = args.get("id").and_then(|i| i.as_str()).unwrap_or("custom");
        let name = args.get("name").and_then(|n| n.as_str()).unwrap_or(id);
        let transport = args
            .get("transport")
            .and_then(|t| t.as_str())
            .unwrap_or("stdio");
        let command = args
            .get("command")
            .and_then(|c| c.as_str())
            .map(String::from);
        let url = args.get("url").and_then(|u| u.as_str()).map(String::from);
        if let Some(url) = &url {
            crate::net_guard::validate_url(url)
                .await
                .map_err(|error| OdonError::Tool {
                    tool: self.name().to_string(),
                    message: format!("Invalid or disallowed MCP SSE URL '{url}': {error}"),
                })?;
        }
        if transport == "stdio" {
            // A stdio MCP server is an arbitrary local command that spawns on
            // demand; it must face the same catastrophic-command policy as
            // shell execution instead of slipping through at Tier 1/0.
            let cmd_line = match &command {
                Some(cmd) => match &args.get("args").and_then(|a| a.as_array()) {
                    Some(items) => format!(
                        "{} {}",
                        cmd,
                        items
                            .iter()
                            .filter_map(|i| i.as_str())
                            .collect::<Vec<_>>()
                            .join(" ")
                    ),
                    None => cmd.clone(),
                },
                None => {
                    return Err(OdonError::Tool {
                        tool: self.name().to_string(),
                        message: "stdio transport requires a 'command' parameter".to_string(),
                    });
                }
            };
            let policy = ctx.approval_engine.get_policy().await;
            if let Some(reason) = policy.command_forbidden_reason(&cmd_line) {
                return Err(OdonError::Security(format!(
                    "MCP stdio command blocked by security policy: {reason}"

                )));
            }
        }
        let server_args = args.get("args").and_then(|a| a.as_array()).map(|items| {
            items
                .iter()
                .filter_map(|item| item.as_str().map(String::from))
                .collect::<Vec<_>>()
        });
        let env = args.get("env").and_then(Value::as_object).map(|values| {
            values
                .iter()
                .filter_map(|(key, value)| {
                    value.as_str().map(|value| (key.clone(), value.to_string()))
                })
                .collect::<HashMap<String, String>>()
        });

        let config = McpServerConfig {
            id: id.to_string(),
            name: name.to_string(),
            transport: transport.to_string(),
            command,
            args: server_args,
            env,
            url,
            enabled: true,
            tools: Vec::new(),
        };

        let mut servers = load_mcp_servers();
        if let Some(pos) = servers.iter().position(|s| s.id == id) {
            servers[pos] = config;
        } else {
            servers.push(config);
        }
        save_mcp_servers(&servers)?;
        Ok(json!({ "id": id, "name": name, "status": "configured", "persisted": true }))
    }
}

