pub struct SettingsSetTool;
#[async_trait]
impl Tool for SettingsSetTool {
    fn name(&self) -> &str {
        "settings_set"
    }
    fn description(&self) -> &str {
        "Update agent execution mode (autonomous, supervised, locked)"
    }
    fn parameters_schema(&self) -> Value {
