                    message: format!(
                        "unrecognized execution mode {mode_str:?}; expected one of autonomous|supervised|locked"
                    ),
                });
            }
        };
        ctx.approval_engine.update_mode(mode).await;
        Ok(json!({ "execution_mode": mode_str, "status": "updated" }))
    }
