use crate::registry::{Tool, ToolContext};

fn project_error(tool: &str, message: String) -> OdonError {
    OdonError::Tool {
        tool: tool.to_string(),
        message,
    }
}

pub struct ProjectDetectTool;
#[async_trait]
impl Tool for ProjectDetectTool {
    fn name(&self) -> &str {
        "project_detect"
    }
    fn description(&self) -> &str {
        "Detect the workspace project type and key configuration files"
    }
    fn parameters_schema(&self) -> Value {
        json!({ "type": "object", "properties": {} })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, ctx: &ToolContext, _args: Value) -> Result<Value> {
        let root = Path::new(&ctx.workspace_root);
        let candidates = [
            ("rust", "Cargo.toml"),
            ("node", "package.json"),
            ("python", "pyproject.toml"),
            ("python", "requirements.txt"),
            ("go", "go.mod"),
            ("dotnet", "*.csproj"),
            ("docker", "docker-compose.yml"),
        ];
        let mut project_types = Vec::new();
        let mut config_files = Vec::new();
        for (kind, file) in candidates {
            let exists = if file.contains('*') {
                std::fs::read_dir(root)
                    .map(|entries| {
                        entries.filter_map(|entry| entry.ok()).any(|entry| {
                            entry
                                .path()
                                .extension()
                                .map(|ext| ext.eq_ignore_ascii_case("csproj"))
                                .unwrap_or(false)
                        })
                    })
                    .unwrap_or(false)
            } else {
                root.join(file).is_file()
            };
            if exists {
                if !project_types.contains(&kind.to_string()) {
                    project_types.push(kind.to_string());
                }
                config_files.push(file.to_string());
            }
        }
        Ok(json!({
            "workspace": ctx.workspace_root,
            "project_types": project_types,
            "config_files": config_files
        }))
    }
}

pub struct DependencyAuditTool;
#[async_trait]
impl Tool for DependencyAuditTool {
    fn name(&self) -> &str {
        "dependency_audit"
    }

fn description(&self) -> &str {
    "Run a dependency audit using Cargo Audit or npm audit when the project is configured"
}
fn parameters_schema(&self) -> Value {
    json!({
        "type": "object",
        "properties": {
            "timeout_secs": { "type": "integer", "description": "Maximum audit duration (default 60, max 300)" }
        }
    })
}
fn risk_tier(&self) -> RiskTier {
    RiskTier::Tier0ReadOnly
}
fn requirements(&self) -> crate::registry::ToolRequirements {
    crate::registry::ToolRequirements {
        binaries: Vec::new(),
        any_binaries: vec!["cargo".into(), "npm".into()],
        environment: vec![],
    }
}
async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
    let timeout_secs = args
        .get("timeout_secs")
        .and_then(Value::as_u64)
        .unwrap_or(60)
        .clamp(1, 300);
    let root = Path::new(&ctx.workspace_root);
    if root.join("Cargo.lock").is_file() {
        let output = tokio::time::timeout(
            std::time::Duration::from_secs(timeout_secs),
            tokio::process::Command::new("cargo")
                .arg("audit")
                .arg("--json")
                .current_dir(root)
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped())
                .output(),
        )
        .await
        .map_err(|_| project_error(self.name(), "Cargo Audit timed out".to_string()))?
        .map_err(|e| {
            project_error(
                self.name(),
                format!("Could not run Cargo Audit; install cargo-audit first: {e}"),
            )
        })?;
        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        let parsed: Value = serde_json::from_str(&stdout).unwrap_or(Value::Null);
        return Ok(json!({
            "ecosystem": "cargo",
            "command": "cargo audit --json",
            "success": output.status.success(),
            "exit_code": output.status.code().unwrap_or(-1),
            "report": parsed,
            "stdout": stdout.chars().take(100_000).collect::<String>(),
            "stderr": stderr.chars().take(20_000).collect::<String>(),
            "timeout_secs": timeout_secs
        }));
    }
    if root.join("package-lock.json").is_file() {
        let output = tokio::time::timeout(
            std::time::Duration::from_secs(timeout_secs),
            tokio::process::Command::new("npm")
                .arg("audit")
                .arg("--json")
                .current_dir(root)
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped())
                .output(),
        )
        .await
        .map_err(|_| project_error(self.name(), "npm audit timed out".to_string()))?
        .map_err(|e| project_error(self.name(), format!("Could not run npm audit: {e}")))?;
        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        let parsed: Value = serde_json::from_str(&stdout).unwrap_or(Value::Null);
        return Ok(json!({
            "ecosystem": "npm",

                "command": "npm audit --json",
                "success": output.status.success(),
                "exit_code": output.status.code().unwrap_or(-1),
                "report": parsed,
                "stdout": stdout.chars().take(100_000).collect::<String>(),
                "stderr": stderr.chars().take(20_000).collect::<String>(),
                "timeout_secs": timeout_secs
            }));
        }
        Err(project_error(
            self.name(),
            "No Cargo.lock or package-lock.json found in the workspace".to_string(),
        ))
    }
}

pub struct ProjectScriptsTool;
#[async_trait]
impl Tool for ProjectScriptsTool {
    fn name(&self) -> &str {
        "project_scripts"
    }
    fn description(&self) -> &str {
        "List runnable project scripts from package.json, Cargo, and known Make targets"
    }
    fn parameters_schema(&self) -> Value {
        json!({ "type": "object", "properties": {} })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, ctx: &ToolContext, _args: Value) -> Result<Value> {
        let root = Path::new(&ctx.workspace_root);
        let mut scripts = Vec::new();

        if let Ok(content) = std::fs::read_to_string(root.join("package.json")) {
            if let Ok(value) = serde_json::from_str::<Value>(&content) {
                if let Some(map) = value.get("scripts").and_then(Value::as_object) {
                    for (name, value) in map {
                        scripts.push(json!({
                            "kind": "npm",
                            "name": name,
                            "command": format!("npm run {name}"),
                            "script": value
                        }));
                    }
                }
            }
        }
        if root.join("Cargo.toml").is_file() {
            for (name, command) in [
                ("build", "cargo build"),
                ("check", "cargo check"),
                ("test", "cargo test"),
                ("format", "cargo fmt --all -- --check"),
                (
                    "lint",
                    "cargo clippy --workspace --all-targets -- -D warnings",
                ),
            ] {
                scripts.push(json!({ "kind": "cargo", "name": name, "command": command }));
            }
        }
        if root.join("Makefile").is_file() {
            if let Ok(content) = std::fs::read_to_string(root.join("Makefile")) {
                for line in content.lines() {
                    let Some((target, rest)) = line.split_once(':') else {
                        continue;
                    };
                    if target.contains(char::is_whitespace)
                        || target.starts_with(['.', '#'])
                        || !rest.trim().is_empty()
                    {
                        continue;
                    }
                    scripts.push(json!({
                        "kind": "make",
                        "name": target.trim(),
                        "command": format!("make {}", target.trim())
                    }));

                }
            }
        }
        if scripts.is_empty() {
            return Err(project_error(
                self.name(),
                "No package.json, Cargo.toml, or Makefile scripts found".to_string(),
            ));
        }
        Ok(json!({ "scripts": scripts, "count": scripts.len() }))
    }
}

use async_trait::async_trait;
use odon_core::{OdonError, Result};
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::time::Duration;

use crate::ops_ext::daemon_json;
use crate::registry::{Tool, ToolContext};

fn storage(ctx: &ToolContext) -> Result<&odon_storage::StorageEngine> {
    ctx.storage.as_deref().ok_or_else(|| OdonError::Tool {
        tool: "provider_ops".to_string(),
        message: "Storage engine unavailable in tool context".to_string(),
    })
}

pub struct ProviderListTool;
#[async_trait]
impl Tool for ProviderListTool {
    fn name(&self) -> &str {
        "provider_list"
    }
    fn description(&self) -> &str {
        "List configured model providers with redacted credentials"
    }
    fn parameters_schema(&self) -> Value {
        json!({ "type": "object", "properties": {} })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, ctx: &ToolContext, _args: Value) -> Result<Value> {
        let configs = storage(ctx)?
            .list_provider_configs()
            .map_err(|e| OdonError::Tool {
                tool: self.name().to_string(),
                message: e.to_string(),
            })?;
        let providers: Vec<Value> = configs
            .iter()
            .map(|config| {
                json!({
                    "provider_id": config.provider_id,
                    "name": config.name,
                    "base_url": config.base_url,
                    "api_key_configured": !config.api_key.trim().is_empty(),
                    "is_default": config.is_default,
                    "models": serde_json::from_str::<Value>(&config.models_json).unwrap_or_else(|_| json!([])),
                    "updated_at": config.updated_at,
                })
            })
            .collect();
        Ok(json!({ "providers": providers, "count": providers.len() }))
    }
}

pub struct ProviderTestTool;
#[async_trait]
impl Tool for ProviderTestTool {
    fn name(&self) -> &str {
        "provider_test"
    }
    fn description(&self) -> &str {
        "Test a configured provider endpoint by fetching models or invoking a model with a tiny prompt"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "provider_id": { "type": "string" },
                "model": { "type": "string", "description": "Optional model ID; when supplied, sends a one-token OpenAI-compatible chat request" }
            },
            "required": ["provider_id"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier1WorkspaceMutating
    }

async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
    let provider_id = args
        .get("provider_id")
        .and_then(Value::as_str)
        .ok_or_else(|| OdonError::Tool {
            tool: self.name().to_string(),
            message: "Missing 'provider_id' parameter".to_string(),
        })?;
    let config = storage(ctx)?
        .get_provider_config(provider_id)
        .map_err(|e| OdonError::Tool {
            tool: self.name().to_string(),
            message: e.to_string(),
        })?
        .ok_or_else(|| OdonError::Tool {
            tool: self.name().to_string(),
            message: format!("Provider '{provider_id}' was not found"),
        })?;

    let base_url = config
        .base_url
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| OdonError::Tool {
            tool: self.name().to_string(),
            message: format!("Provider '{provider_id}' has no base URL"),
        })?
        .trim_end_matches('/')
        .to_string();
    let model = args
        .get("model")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let endpoint = if model.is_some() {
        format!("{base_url}/chat/completions")
    } else {
        format!("{base_url}/models")
    };
    let validated = crate::net_guard::validate_url(&endpoint).await?;
    let started = std::time::Instant::now();
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(crate::net_guard::redirect_policy(
            validated.host_str().unwrap_or("").to_string(),
        ))
        .build()
        .map_err(|e| OdonError::Tool {
            tool: self.name().to_string(),
            message: e.to_string(),
        })?;
    let mut request = if model.is_some() {
        client.post(validated.clone()).json(&json!({
            "model": model,
            "messages": [{ "role": "user", "content": "ping" }],
            "max_tokens": 1,
            "stream": false
        }))
    } else {
        client.get(validated.clone())
    };
    if !config.api_key.trim().is_empty() {
        request = request.bearer_auth(config.api_key.trim());
    }
    let response = request.send().await.map_err(|e| OdonError::Tool {
        tool: self.name().to_string(),
        message: format!("Provider request failed: {e}"),
    })?;
    let status = response.status().as_u16();
    let body = response.text().await.unwrap_or_default();
    let parsed: Value = serde_json::from_str(&body).unwrap_or(Value::Null);
    let models: Vec<String> = parsed
        .pointer("/data")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| item.get("id").and_then(Value::as_str))
                .map(String::from)

                    .collect()
            })
            .unwrap_or_default();
        let completion = if model.is_some() {
            parsed
                .pointer("/choices/0/message/content")
                .and_then(Value::as_str)
                .map(String::from)
        } else {
            None
        };
        Ok(json!({
            "provider_id": provider_id,
            "endpoint": validated.as_str(),
            "model": model,
            "status_code": status,
            "success": (200..300).contains(&status),
            "model_count": models.len(),
            "models": models,
            "completion": completion,
            "duration_ms": started.elapsed().as_millis()
        }))
    }
}

pub struct ProviderDeleteTool;
#[async_trait]
impl Tool for ProviderDeleteTool {
    fn name(&self) -> &str {
        "provider_delete"
    }
    fn description(&self) -> &str {
        "Remove a configured OpenAI-compatible provider and its stored credential"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "provider_id": { "type": "string" },
                "confirm": { "type": "boolean", "description": "Must be true" }
            },
            "required": ["provider_id", "confirm"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier2SystemMutating
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let provider_id = args
            .get("provider_id")
            .and_then(Value::as_str)
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: "Missing 'provider_id' parameter".to_string(),
            })?;
        if !args
            .get("confirm")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            return Err(OdonError::Tool {
                tool: self.name().to_string(),
                message: "Set confirm=true to remove this provider credential".to_string(),
            });
        }
        let engine = storage(ctx)?;
        let existing = engine
            .get_provider_config(provider_id)
            .map_err(|e| OdonError::Tool {
                tool: self.name().to_string(),
                message: e.to_string(),
            })?
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: format!("Provider '{provider_id}' was not found"),
            })?;
        // Ask the daemon first so the in-memory provider is unregistered too;
        // fall back to direct storage for CLI-only execution contexts.
        let daemon_deleted = daemon_json(
            reqwest::Method::DELETE,

            &format!("/api/providers/config/{}", provider_id),
            None,
            self.name(),
        )
        .await
        .map(|(status, _)| (200..300).contains(&status))
        .unwrap_or(false);
        let deleted = daemon_deleted
            || engine
                .delete_provider_config(provider_id)
                .map_err(|e| OdonError::Tool {
                    tool: self.name().to_string(),
                    message: e.to_string(),
                })?;
        Ok(json!({
            "provider_id": provider_id,
            "was_default": existing.is_default,
            "deleted": deleted,
            "runtime_unregistered": daemon_deleted,
            "status": "removed"
        }))
    }
}

pub struct ProviderSetDefaultTool;
#[async_trait]
impl Tool for ProviderSetDefaultTool {
    fn name(&self) -> &str {
        "provider_set_default"
    }
    fn description(&self) -> &str {
        "Mark a configured model provider as the default"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "provider_id": { "type": "string" }
            },
            "required": ["provider_id"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier1WorkspaceMutating
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let provider_id = args
            .get("provider_id")
            .and_then(Value::as_str)
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: "Missing 'provider_id' parameter".to_string(),
            })?;
        let engine = storage(ctx)?;
        let config = engine
            .get_provider_config(provider_id)
            .map_err(|e| OdonError::Tool {
                tool: self.name().to_string(),
                message: e.to_string(),
            })?
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: format!("Provider '{provider_id}' was not found"),
            })?;
        let models = serde_json::from_str::<Vec<String>>(&config.models_json).unwrap_or_default();
        // Ask the daemon first so the in-memory runtime default is updated too;
        // fall back to direct storage for CLI-only execution contexts.
        let daemon_updated = daemon_json(
            reqwest::Method::POST,
            "/api/providers/config",
            Some(json!({
                "provider_id": config.provider_id,
                "api_key": config.api_key,
                "base_url": config.base_url,
                "is_default": true,
                "name": config.name,
                "models": models
            })),
            self.name(),
        )

        .await
        .map(|(status, _)| (200..300).contains(&status))
        .unwrap_or(false);
        if !daemon_updated {
            engine
                .save_provider_config(
                    &config.provider_id,
                    &config.api_key,
                    config.base_url.as_deref(),
                    true,
                    config.name.as_deref(),
                    &config.models_json,
                )
                .map_err(|e| OdonError::Tool {
                    tool: self.name().to_string(),
                    message: e.to_string(),
                })?;
        }
        Ok(json!({
            "provider_id": provider_id,
            "is_default": true,
            "runtime_updated": daemon_updated,
            "status": "updated"
        }))
    }
}

use crate::registry::{Tool, ToolContext};
use async_trait::async_trait;
use odon_core::error::{OdonError, Result};
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::time::Duration;
use tokio::process::Command;

const COMMAND_TIMEOUT: Duration = Duration::from_secs(300);
const OUTPUT_LIMIT: usize = 64 * 1024;

pub struct FormatCodeTool;

#[async_trait]
impl Tool for FormatCodeTool {
    fn name(&self) -> &str {
        "format_code"
    }
    fn description(&self) -> &str {
        "Format explicitly selected source files with the workspace's installed language formatter"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["paths"],
            "properties": {
                "paths": {
                    "type": "array", "minItems": 1, "maxItems": 100,
                    "items": { "type": "string" }
                }
            }
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier2SystemMutating
    }

    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let workspace = canonical_workspace(ctx, self.name())?;
        let requested = args
            .get("paths")
            .and_then(Value::as_array)
            .ok_or_else(|| tool_message(self.name(), "paths must be an array"))?;
        if requested.is_empty() || requested.len() > 100 {
            return tool_error(self.name(), "paths must contain between 1 and 100 files");
        }

        let mut groups = BTreeMap::<&str, Vec<PathBuf>>::new();
        for value in requested {
            let input = value
                .as_str()
                .ok_or_else(|| tool_message(self.name(), "every path must be a string"))?;
            let path = resolve_existing(&workspace, input, self.name())?;
            if !path.is_file() {
                return tool_error(self.name(), format!("{} is not a file", path.display()));
            }
            let language = formatter_kind(&path).ok_or_else(|| {
                tool_message(
                    self.name(),
                    format!("no supported formatter for {}", path.display()),
                )
            })?;
            groups.entry(language).or_default().push(path);
        }

        let mut runs = Vec::new();
        for (kind, paths) in groups {
            let (program, arguments) = formatter_command(kind, &workspace, &paths)?;
            let result = run_command(self.name(), &workspace, &program, &arguments).await?;
            if !result.success {
                return Err(command_failure(self.name(), &result));
            }
            runs.push(result);
        }
        Ok(json!({ "formatted": requested.len(), "runs": runs }))
    }
}

pub struct RunChecksTool;

#[async_trait]
impl Tool for RunChecksTool {
    fn name(&self) -> &str {
        "run_checks"
    }
    fn description(&self) -> &str {
        "Detect the project toolchain and run its test or lint command with timeout and captured output"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["kind"],
            "properties": {
                "kind": { "type": "string", "enum": ["test", "lint"] },
                "path": { "type": "string", "description": "Workspace-relative project directory" }
            }
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier2SystemMutating
    }

    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let workspace = canonical_workspace(ctx, self.name())?;
        let root = resolve_existing(
            &workspace,
            args.get("path").and_then(Value::as_str).unwrap_or("."),
            self.name(),
        )?;
        if !root.is_dir() {
            return tool_error(
                self.name(),
                format!("{} is not a directory", root.display()),
            );
        }
        let kind = args.get("kind").and_then(Value::as_str).unwrap_or("");
        if kind != "test" && kind != "lint" {
            return tool_error(self.name(), "kind must be 'test' or 'lint'");
        }
        let (project, program, arguments) = detect_check_command(&root, kind)?;
        let result = run_command(self.name(), &root, &program, &arguments).await?;
        if !result.success {
            return Err(command_failure(self.name(), &result));
        }
        Ok(json!({ "project": project, "kind": kind, "result": result }))
    }
}

pub struct TestFileTool;

#[async_trait]
impl Tool for TestFileTool {
    fn name(&self) -> &str {
        "test_file"
    }
    fn description(&self) -> &str {
        "Run the narrowest supported test command for one test file without shell interpolation"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["file"],
            "properties": {
                "file": { "type": "string", "minLength": 1 }
            }
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier2SystemMutating
    }

    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value> {
        let workspace = canonical_workspace(ctx, self.name())?;
        let file = resolve_existing(
            &workspace,
            args.get("file").and_then(Value::as_str).unwrap_or(""),
            self.name(),
        )?;
        if !file.is_file() {
            return tool_error(self.name(), format!("{} is not a file", file.display()));
        }
        let root = find_project_root(&workspace, &file).ok_or_else(|| {
            tool_message(
                self.name(),
                "no supported project manifest found for test file",
            )
        })?;
        let (project, program, arguments) = test_file_command(&root, &file)?;
        let result = run_command(self.name(), &root, &program, &arguments).await?;
        if !result.success {
            return Err(command_failure(self.name(), &result));
        }
        Ok(json!({
            "project": project,
            "file": path_for_output(file.strip_prefix(&workspace).unwrap_or(&file)),
            "result": result
        }))
    }
}

#[derive(Debug, serde::Serialize)]
struct CommandResult {
    program: String,
    arguments: Vec<String>,
    exit_code: Option<i32>,
    success: bool,
    stdout: String,
    stderr: String,
    truncated: bool,
}

async fn run_command(
    tool: &str,
    directory: &Path,
    program: &str,
    args: &[String],
) -> Result<CommandResult> {
    let output = tokio::time::timeout(
        COMMAND_TIMEOUT,
        Command::new(program)
            .args(args)
            .current_dir(directory)
            .kill_on_drop(true)
            .output(),
    )
    .await
    .map_err(|_| {
        tool_message(
            tool,
            format!(
                "command timed out after {} seconds",
                COMMAND_TIMEOUT.as_secs()
            ),
        )
    })?
    .map_err(|error| tool_message(tool, format!("failed to start '{program}': {error}")))?;

    let (stdout, stdout_truncated) = bounded_output(&output.stdout);
    let (stderr, stderr_truncated) = bounded_output(&output.stderr);
    Ok(CommandResult {
        program: program.to_string(),
        arguments: args.to_vec(),
        exit_code: output.status.code(),
        success: output.status.success(),
        stdout,
        stderr,
        truncated: stdout_truncated || stderr_truncated,
    })
}

fn formatter_kind(path: &Path) -> Option<&'static str> {
    match path.extension()?.to_str()?.to_ascii_lowercase().as_str() {
        "rs" => Some("rust"),
        "go" => Some("go"),
        "py" | "pyi" => Some("python"),
        "js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs" | "json" | "css" | "scss" | "md" | "yaml"
        | "yml" => Some("web"),
        _ => None,
    }
}

fn formatter_command(
    kind: &str,
    workspace: &Path,
    paths: &[PathBuf],
) -> Result<(String, Vec<String>)> {
    let relative = paths
        .iter()
        .map(|path| path_for_output(path.strip_prefix(workspace).unwrap_or(path)))
        .collect::<Vec<_>>();
    match kind {
        "rust" => {
            let mut args = vec!["--edition".into(), "2021".into()];
            args.extend(relative);
            Ok(("rustfmt".into(), args))
        }
        "go" => {
            let mut args = vec!["-w".into()];
            args.extend(relative);
            Ok(("gofmt".into(), args))
        }
        "python" => {
            let mut args = vec!["format".into()];
            args.extend(relative);
            Ok(("ruff".into(), args))
        }
        "web" => {
            let biome = local_binary(workspace, "biome");
            let prettier = local_binary(workspace, "prettier");
            if biome.is_file() {
                let mut args = vec!["format".into(), "--write".into()];
                args.extend(relative);
                Ok((path_for_output(&biome), args))
            } else if prettier.is_file() {
                let mut args = vec!["--write".into()];
                args.extend(relative);
                Ok((path_for_output(&prettier), args))
            } else {
                tool_error("format_code", "no local Biome or Prettier executable found")
            }
        }
        _ => tool_error(
            "format_code",
            format!("unsupported formatter kind '{kind}'"),
        ),
    }
}

fn detect_check_command(root: &Path, kind: &str) -> Result<(String, String, Vec<String>)> {
    if root.join("Cargo.toml").is_file() {
        let args = if kind == "test" {
            vec!["test".into()]
        } else {
            vec![
                "clippy".into(),
                "--all-targets".into(),
                "--".into(),
                "-D".into(),
                "warnings".into(),
            ]
        };
        return Ok(("rust".into(), "cargo".into(), args));
    }
    if root.join("package.json").is_file() {
        let package_manager = package_manager(root);
        let script = package_script(root, kind)?;
        return Ok(("node".into(), package_manager, vec!["run".into(), script]));
    }
    if root.join("pyproject.toml").is_file() {
        return if kind == "test" {

            Ok((
                "python".into(),
                "python".into(),
                vec!["-m".into(), "pytest".into()],
            ))
        } else {
            Ok((
                "python".into(),
                "ruff".into(),
                vec!["check".into(), ".".into()],
            ))
        };
    }
    if root.join("go.mod").is_file() {
        return if kind == "test" {
            Ok((
                "go".into(),
                "go".into(),
                vec!["test".into(), "./...".into()],
            ))
        } else {
            Ok(("go".into(), "go".into(), vec!["vet".into(), "./...".into()]))
        };
    }
    tool_error("run_checks", "no supported project manifest found")
}

fn test_file_command(root: &Path, file: &Path) -> Result<(String, String, Vec<String>)> {
    let relative = path_for_output(file.strip_prefix(root).unwrap_or(file));
    if root.join("Cargo.toml").is_file() {
        let stem = file
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("");
        let is_integration = file
            .strip_prefix(root)
            .ok()
            .and_then(|path| path.components().next())
            .map(|part| part.as_os_str() == "tests")
            .unwrap_or(false);
        let args = if is_integration {
            vec!["test".into(), "--test".into(), stem.into()]
        } else {
            vec!["test".into(), stem.into()]
        };
        return Ok(("rust".into(), "cargo".into(), args));
    }
    if root.join("package.json").is_file() {
        let manager = package_manager(root);
        let script = package_script(root, "test")?;
        return Ok((
            "node".into(),
            manager,
            vec!["run".into(), script, "--".into(), relative],
        ));
    }
    if root.join("pyproject.toml").is_file() {
        return Ok((
            "python".into(),
            "python".into(),
            vec!["-m".into(), "pytest".into(), relative],
        ));
    }
    if root.join("go.mod").is_file() {
        let directory = file
            .parent()
            .unwrap_or(root)
            .strip_prefix(root)
            .unwrap_or(Path::new("."));
        return Ok((
            "go".into(),
            "go".into(),
            vec!["test".into(), format!("./{}", path_for_output(directory))],
        ));
    }
    tool_error("test_file", "no supported project manifest found")
}

fn package_manager(root: &Path) -> String {
    if root.join("pnpm-lock.yaml").is_file() {
        "pnpm".into()
    } else if root.join("yarn.lock").is_file() {
        "yarn".into()
    } else {
        "npm".into()
    }
}

fn package_script(root: &Path, kind: &str) -> Result<String> {
    let bytes = std::fs::read(root.join("package.json"))
        .map_err(|error| tool_message("run_checks", error))?;
    let package: Value =
        serde_json::from_slice(&bytes).map_err(|error| tool_message("run_checks", error))?;
    let scripts = package.get("scripts").and_then(Value::as_object);
    let candidates: &[&str] = if kind == "test" {
        &["test"]
    } else {
        &["lint", "check"]
    };
    candidates
        .iter()
        .find(|name| scripts.and_then(|items| items.get(**name)).is_some())
        .map(|name| (*name).to_string())
        .ok_or_else(|| tool_message("run_checks", format!("package.json has no {kind} script")))
}

fn find_project_root(workspace: &Path, file: &Path) -> Option<PathBuf> {
    let mut current = file.parent()?;
    loop {
        if ["Cargo.toml", "package.json", "pyproject.toml", "go.mod"]
            .iter()
            .any(|manifest| current.join(manifest).is_file())
        {
            return Some(current.to_path_buf());
        }
        if current == workspace {
            return None;
        }
        current = current.parent()?;
        if !current.starts_with(workspace) {
            return None;
        }
    }
}

fn local_binary(root: &Path, name: &str) -> PathBuf {
    let extension = if cfg!(windows) { ".cmd" } else { "" };
    root.join("node_modules")
        .join(".bin")
        .join(format!("{name}{extension}"))
}

fn canonical_workspace(ctx: &ToolContext, tool: &str) -> Result<PathBuf> {
    std::path::Path::new(&ctx.workspace_root)
        .canonicalize()
        .map_err(|error| tool_message(tool, error))
}

fn resolve_existing(workspace: &Path, input: &str, tool: &str) -> Result<PathBuf> {
    let candidate = Path::new(input);
    let joined = if candidate.is_absolute() {
        candidate.to_path_buf()
    } else {
        workspace.join(candidate)
    };
    let resolved = joined
        .canonicalize()
        .map_err(|error| tool_message(tool, error))?;
    if !resolved.starts_with(workspace) {
        return tool_error(tool, "path escapes the workspace boundary");
    }
    Ok(resolved)
}

fn bounded_output(bytes: &[u8]) -> (String, bool) {
    let truncated = bytes.len() > OUTPUT_LIMIT;
    let slice = if truncated {
        &bytes[bytes.len() - OUTPUT_LIMIT..]
    } else {
        bytes
    };
    (String::from_utf8_lossy(slice).into_owned(), truncated)
}

fn command_failure(tool: &str, result: &CommandResult) -> OdonError {
    OdonError::Tool {
        tool: tool.to_string(),
        message: format!(
            "{} exited with code {:?}\nstdout:\n{}\nstderr:\n{}",
            result.program, result.exit_code, result.stdout, result.stderr
        ),
    }
}

fn path_for_output(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn tool_error<T>(tool: &str, message: impl std::fmt::Display) -> Result<T> {
    Err(tool_message(tool, message))
}

fn tool_message(tool: &str, message: impl std::fmt::Display) -> OdonError {
    OdonError::Tool {
        tool: tool.to_string(),
        message: message.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn output_is_bounded_from_the_tail() {
        let bytes = vec![b'x'; OUTPUT_LIMIT + 10];
        let (output, truncated) = bounded_output(&bytes);
        assert!(truncated);
        assert_eq!(output.len(), OUTPUT_LIMIT);
    }

    #[test]
    fn detects_supported_formatters() {
        assert_eq!(formatter_kind(Path::new("src/lib.rs")), Some("rust"));
        assert_eq!(formatter_kind(Path::new("src/app.tsx")), Some("web"));
        assert_eq!(formatter_kind(Path::new("asset.png")), None);
    }
}

use async_trait::async_trait;
use odon_core::{OdonError, Result};
use odon_security::{ApprovalDecision, ApprovalEngine, AuditLogger, RiskTier};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "snake_case")]
pub enum ToolAvailability {
    Stable,
    Experimental,
    Unavailable { reason: String },
}

impl ToolAvailability {
    pub fn label(&self) -> &'static str {
        match self {
            Self::Stable => "stable",
            Self::Experimental => "experimental",
            Self::Unavailable { .. } => "unavailable",
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ToolRequirements {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub binaries: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub any_binaries: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub environment: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ToolVisibility {
    /// Sent to the model as a first-class tool.
    Model,
    /// Still executable for compatibility, but not advertised to the model.
    Compatibility,
    /// Local/host tool that must only be exposed when its capability is present.
    HostOnly,
}

impl ToolVisibility {
    pub fn label(&self) -> &'static str {
        match self {
            Self::Model => "model",
            Self::Compatibility => "compatibility",
            Self::HostOnly => "host",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolSchema {
    pub name: String,
    pub description: String,
    pub parameters: Value,
    pub risk_tier: u8,
    pub availability: ToolAvailability,
    pub requirements: ToolRequirements,
    pub visibility: ToolVisibility,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolDiagnostic {
    pub name: String,
    pub availability: ToolAvailability,
    pub visibility: ToolVisibility,
    pub ready: bool,
    pub issues: Vec<String>,
}

#[derive(Clone)]

pub struct ToolContext {
    pub session_id: String,
    pub workspace_root: String,
    pub approval_engine: Arc<ApprovalEngine>,
    pub audit_logger: Arc<AuditLogger>,
    pub storage: Option<Arc<odon_storage::StorageEngine>>,
}

#[async_trait]
pub trait Tool: Send + Sync {
    fn name(&self) -> &str;
    fn description(&self) -> &str;
    fn parameters_schema(&self) -> Value;
    fn risk_tier(&self) -> RiskTier;
    fn availability(&self) -> ToolAvailability {
        ToolAvailability::Stable
    }
    fn requirements(&self) -> ToolRequirements {
        ToolRequirements::default()
    }

    async fn execute(&self, ctx: &ToolContext, args: Value) -> Result<Value>;
}

pub struct ToolRegistry {
    tools: HashMap<String, Box<dyn Tool>>,
}

impl Default for ToolRegistry {
    fn default() -> Self {
        Self::new()
    }
}

fn binary_on_path(binary: &str) -> bool {
    let candidate = Path::new(binary);
    if candidate.components().count() > 1 {
        return candidate.is_file();
    }

    let Some(path) = std::env::var_os("PATH") else {
        return false;
    };
    let extensions = if cfg!(windows) {
        std::env::var_os("PATHEXT")
            .map(|value| {
                value
                    .to_string_lossy()
                    .split(';')
                    .filter(|item| !item.is_empty())
                    .map(str::to_string)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![".COM".into(), ".EXE".into(), ".BAT".into(), ".CMD".into()])
    } else {
        vec![String::new()]
    };

    let found_on_path = std::env::split_paths(&path).any(|directory| {
        extensions
            .iter()
            .any(|extension| directory.join(format!("{binary}{extension}")).is_file())
    });
    if found_on_path || !cfg!(windows) {
        return found_on_path;
    }

    // Chrome and Edge installers normally do not add themselves to PATH on
    // Windows, while the browser-session implementation intentionally probes
    // their standard install directories. Diagnostics must use the same
    // capability check or the desktop hides a working browser tool.
    let executable = match binary {
        "chrome" | "google-chrome" | "chromium" => Some(("Google", "Chrome", "chrome.exe")),
        "msedge" | "microsoft-edge" => Some(("Microsoft", "Edge", "msedge.exe")),
        _ => None,
    };
    let Some((vendor, product, executable)) = executable else {
        return false;
    };
    ["PROGRAMFILES", "PROGRAMFILES(X86)", "LOCALAPPDATA"]
        .iter()
        .filter_map(std::env::var_os)
        .map(std::path::PathBuf::from)
        .any(|base| {
            base.join(vendor)
                .join(product)
                .join("Application")
                .join(executable)
                .is_file()
        })
}

impl ToolRegistry {
    pub fn new() -> Self {
        Self {
            tools: HashMap::new(),
        }
    }

    pub fn register(&mut self, tool: Box<dyn Tool>) {
        let name = tool.name().to_string();
        assert!(
            !self.tools.contains_key(&name),
            "duplicate tool registration: {name}"
        );
        self.tools.insert(name, tool);
    }

    pub fn normalize_name(name: &str) -> String {
        let stripped = name
            .trim()
            .trim_start_matches("defaultapi:")
            .trim_start_matches("default_api:")
            .trim_start_matches("functions.")
            .trim_start_matches("function.")
            .trim_start_matches("tools:")
            .trim_start_matches("tool:")
            .trim();

        let lower = stripped.to_lowercase().replace('-', "_");
        match lower.as_str() {
            "websearch" | "search_web" | "search" | "google_search" | "duckduckgo_search" => {
                "web_search".to_string()
            }
            "websearch_news" | "search_news" | "news_search" | "news" => {
                "web_search_news".to_string()
            }
            "websearch_code" | "search_code" => "web_search_code".to_string(),
            "codesearch" | "code_search" => "code_search".to_string(),
            "fetch" | "http_get" | "curl" | "browse" => "web_fetch".to_string(),
            "readfile" | "read" | "fs_read" => "read_file".to_string(),
            "writefile" | "write" | "fs_write" => "write_file".to_string(),
            "listdirectory" | "list_dir" | "listdir" | "ls" => "list_directory".to_string(),
            "createdirectory" | "create_dir" | "mkdir" => "create_directory".to_string(),
            "deletefile" | "rm" | "fs_delete" => "delete_file".to_string(),
            "bash" | "shell" | "sh" | "terminal" => "bash_run".to_string(),
            "fs_chown" => "fs_owner_check".to_string(),
            "processlist" | "ps" => "process_list".to_string(),
            "memorysearch" => "memory_search".to_string(),
            "termigopastebuffer_history" | "termigopastebufferhistory" => {
                "termigo_paste_buffer_history".to_string()
            }
            _ => lower,
        }
    }

pub fn get(&self, name: &str) -> Option<&dyn Tool> {
    if let Some(tool) = self.tools.get(name) {
        return Some(tool.as_ref());
    }
    let norm = Self::normalize_name(name);
    self.tools.get(&norm).map(|tool| tool.as_ref())
}

pub fn contains(&self, name: &str) -> bool {
    if self.tools.contains_key(name) {
        return true;
    }
    let norm = Self::normalize_name(name);
    self.tools.contains_key(&norm)
}

fn visibility_for_name(name: &str) -> ToolVisibility {
    matches!(
        name,
        "fs_read"
            | "fs_write"
            | "fs_edit"
            | "fs_list"
            | "fs_search"
            | "fs_delete"
            | "bash_run"
            | "terminal_exec"
            | "cron_add"
            | "cron_list"
            | "cron_remove"
            // Security-perimeter tools: never advertised to the model.
            | "approval_decide"
            | "settings_set"
            | "workspace_add"
            | "mcp_add_server"
    )
    .then_some(ToolVisibility::Compatibility)
    .unwrap_or(ToolVisibility::Model)
}

fn schema_for(tool: &dyn Tool) -> ToolSchema {
    ToolSchema {
        name: tool.name().to_string(),
        description: tool.description().to_string(),
        parameters: tool.parameters_schema(),
        risk_tier: tool.risk_tier() as u8,
        availability: tool.availability(),
        requirements: tool.requirements(),
        visibility: Self::visibility_for_name(tool.name()),
    }
}

/// Model-facing schemas only. Compatibility wrappers remain executable via
/// `get`/`execute_tool`, but are not advertised as separate capabilities.
pub fn schemas(&self) -> Vec<ToolSchema> {
    let mut schemas = self
        .tools
        .values()
        .map(|tool| Self::schema_for(tool.as_ref()))
        .filter(|schema| schema.visibility == ToolVisibility::Model)
        .collect::<Vec<_>>();
    schemas.sort_by(|a, b| a.name.cmp(&b.name));
    schemas
}

/// Complete registry, including compatibility and host-gated tools.
pub fn all_schemas(&self) -> Vec<ToolSchema> {
    let mut schemas = self
        .tools
        .values()
        .map(|tool| Self::schema_for(tool.as_ref()))
        .collect::<Vec<_>>();
    schemas.sort_by(|a, b| a.name.cmp(&b.name));
    schemas
}

pub fn diagnostics(&self) -> Vec<ToolDiagnostic> {
    let mut diagnostics = self
        .tools
        .values()
        .map(|tool| {
            let availability = tool.availability();
            let requirements = tool.requirements();
            let mut issues = Vec::new();

            if let ToolAvailability::Unavailable { reason } = &availability {
                issues.push(reason.clone());
            }
            for binary in &requirements.binaries {
                if !binary_on_path(binary) {
                    issues.push(format!("required binary '{binary}' was not found on PATH"));
                }
            }
            if !requirements.any_binaries.is_empty() {
                let available = requirements
                    .any_binaries
                    .iter()
                    .any(|binary| binary_on_path(binary));
                if !available {
                    issues.push(format!(
                        "requires at least one of these binaries on PATH: {}",
                        requirements.any_binaries.join(", ")
                    ));
                }
            }
            for variable in &requirements.environment {
                if std::env::var(variable)
                    .map(|value| value.trim().is_empty())
                    .unwrap_or(true)
                {
                    issues.push(format!(
                        "required environment variable '{variable}' is not set"
                    ));
                }
            }

            if tool.parameters_schema().get("type").and_then(Value::as_str) != Some("object") {
                issues.push("parameter schema root must have type 'object'".to_string());
            }

            ToolDiagnostic {
                name: tool.name().to_string(),
                availability,
                visibility: Self::visibility_for_name(tool.name()),
                ready: issues.is_empty(),
                issues,
            }
        })
        .collect::<Vec<_>>();
    diagnostics.sort_by(|a, b| a.name.cmp(&b.name));
    diagnostics
}

pub async fn execute_tool(&self, name: &str, ctx: &ToolContext, args: Value) -> Result<Value> {
    let tool = self.get(name).ok_or_else(|| OdonError::Tool {
        tool: name.to_string(),
        message: format!("Tool '{}' not found in registry", name),
    })?;
    // Use the canonical registered name so compatibility aliases receive
    // the same risk policy and audit trail as the primary implementation.
    let canonical_name = tool.name();

    if let ToolAvailability::Unavailable { reason } = tool.availability() {
        return Err(OdonError::Tool {
            tool: name.to_string(),
            message: format!("Tool is unavailable in this build: {reason}"),
        });
    }

    let desc = format!("Executing tool: {}", canonical_name);
    let start = std::time::Instant::now();

// Plan mode: only read-only tools may run until the plan is accepted.
if tool.risk_tier() > RiskTier::Tier0ReadOnly {
    if let Some(storage) = &ctx.storage {
        if crate::harness::is_plan_mode(storage, &ctx.session_id) {
            return Err(OdonError::Tool {
                tool: name.to_string(),
                message: "Plan mode is active: only read-only tools are allowed. Present the plan, then call plan_mode with enabled=false to execute.".to_string(),
            });
        }
    }
}

// Hard command-policy check before approval: catastrophic commands are
// refused regardless of the execution mode or a stored "always allow".
for key in ["command", "script"] {
    if let Some(command) = args.get(key).and_then(|value| value.as_str()) {
        let policy = ctx.approval_engine.get_policy().await;
        if let Some(reason) = policy.command_forbidden_reason(command) {
            let _ = ctx
                .audit_logger
                .record(
                    &ctx.session_id,
                    canonical_name,
                    tool.risk_tier(),
                    &format!("Blocked by command policy: {reason}"),
                    false,
                    false,
                    0,
                )
                .await;
            return Err(OdonError::Security(format!(
                "Command blocked by security policy: {reason}"
            )));
        }
    }
}

// Security approval check
let decision = ctx
    .approval_engine
    .evaluate_and_request(&ctx.session_id, canonical_name, &args, &desc)
    .await
    .map_err(OdonError::Security)?;

match decision {
    ApprovalDecision::Approved
    | ApprovalDecision::ApprovedAlways
    | ApprovalDecision::ApprovedAll => {
        let res = tool.execute(ctx, args).await;
        let duration = start.elapsed().as_millis() as u64;
        let is_ok = res.is_ok();

        ctx.audit_logger
            .record(
                &ctx.session_id,
                canonical_name,
                tool.risk_tier(),
                &desc,
                true,
                is_ok,
                duration,
            )
            .await;

        res
    }
    ApprovalDecision::Rejected { reason } => {
        ctx.audit_logger
            .record(
                &ctx.session_id,
                canonical_name,
                tool.risk_tier(),
                &format!("Rejected: {}", reason),
                false,
                false,
                start.elapsed().as_millis() as u64,
            )
            .await;

                Err(OdonError::Security(format!(
                    "Tool '{}' execution rejected: {}",
                    name, reason
                )))
            }
            ApprovalDecision::Expired => {
                ctx.audit_logger
                    .record(
                        &ctx.session_id,
                        canonical_name,
                        tool.risk_tier(),
                        "Approval request timed out",
                        false,
                        false,
                        start.elapsed().as_millis() as u64,
                    )
                    .await;

                Err(OdonError::Security(format!(
                    "Tool '{}' approval request timed out",
                    name
                )))
            }
        }
    }
}

use crate::registry::{Tool, ToolContext};
