            .and_then(Value::as_str)
            .map(|s| s.to_string());
        let diff = read_workspace_diff(&ctx.workspace_root, "HEAD", path_filter.as_deref()).await?;
        let summary = summarize_diff(&diff);
        Ok(json!({ "base": "HEAD", "summary": summary }))
    }
}

#[derive(Debug, serde::Serialize)]
struct Finding {
    severity: &'static str,
    category: &'static str,
    path: String,
    line: Option<usize>,
    finding: String,
    suggested_fix: Option<String>,
}

fn review_diff_content(diff: &str) -> Vec<Finding> {
    let mut findings = Vec::new();
    for (relative_path, line, current) in parse_diff_lines(diff) {
        if let Some(finding) = review_line(&relative_path, line, current) {
            findings.push(finding);
        }
    }
    findings
}

fn review_file_content(relative_path: &str, content: &str) -> Vec<Finding> {
    let mut findings = Vec::new();
    for (index, line) in content.lines().enumerate() {
        if let Some(finding) = review_line(relative_path, index + 1, line) {
            findings.push(finding);
        }
    }
    findings
}

fn review_line(relative_path: &str, line: usize, text: &str) -> Option<Finding> {
    let normalized = text.trim();
    if normalized.is_empty() {
        return None;
    }
    let lowered = normalized.to_ascii_lowercase();
    if lowered.starts_with("unsafe ") {
        return Some(Finding {
            severity: "high",
            category: "safety",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some("Keep unsafe blocks minimal, document the invariant, and isolate behind a safe API.".to_string()),
        });
    }
    if lowered.contains("unwrap()") {
        return Some(Finding {
            severity: "medium",
            category: "robustness",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some("Prefer explicit error handling or context-aware unwrap_or_else with a useful message.".to_string()),
        });
    }
    if lowered.contains("expect(\"") && !lowered.contains("expect(\"\"") {
        return Some(Finding {
            severity: "low",
            category: "clarity",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some(
                "Use a more specific message or replace with context-aware error handling."
                    .to_string(),
            ),
        });
    }
    if lowered.contains("todo!") || lowered.contains("unimplemented!") {
        return Some(Finding {
            severity: "medium",
            category: "correctness",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some(
                "Implement the branch or gate it behind an explicit feature flag.".to_string(),
            ),
        });
    }
    None
}

fn security_review_diff(diff: &str) -> Vec<Finding> {
    let mut findings = Vec::new();
    for (relative_path, line, current) in parse_diff_lines(diff) {
        if let Some(finding) = security_review_line(&relative_path, line, current) {
            findings.push(finding);
        }
    }
    findings
}

fn security_review_file(relative_path: &str, content: &str) -> Vec<Finding> {
    let mut findings = Vec::new();
    for (index, line) in content.lines().enumerate() {
        if let Some(finding) = security_review_line(relative_path, index + 1, line) {
            findings.push(finding);
        }
    }
    findings
}

fn security_review_line(relative_path: &str, line: usize, text: &str) -> Option<Finding> {
    let normalized = text.trim();
    if normalized.is_empty() {
        return None;
    }
    let lowered = normalized.to_ascii_lowercase();
    if lowered.contains("secret")
        && (lowered.contains("print") || lowered.contains("log") || lowered.contains("eprint"))
    {
        return Some(Finding {
            severity: "critical",
            category: "secrets",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some("Remove secret material from logs; use a redaction helper or structured logging with allowlists.".to_string()),
        });
    }
    if lowered.contains("password") && lowered.contains("=") {
        return Some(Finding {
            severity: "high",
            category: "secrets",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some(
                "Use a secrets manager or environment-backed config instead of inline credentials."
                    .to_string(),
            ),
        });
    }
    if lowered.contains("eval(") || lowered.contains("exec(") || lowered.contains("execsync(") {
        return Some(Finding {
            severity: "high",
            category: "injection",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some("Avoid dynamic evaluation on untrusted input; use a safe parser or command allowlist.".to_string()),
        });
    }
    if lowered.contains("http://") && !lowered.contains("localhost") {
        return Some(Finding {
            severity: "medium",
            category: "transport",
            path: relative_path.to_string(),
            line: Some(line),
            finding: normalized.to_string(),
            suggested_fix: Some(
                "Prefer HTTPS or internal TLS; validate certificate pinning if applicable."
                    .to_string(),
            ),
        });
    }
    None
}

fn summarize_diff(diff: &str) -> Value {
    let mut files = Vec::new();
    let mut additions = 0usize;
    let mut deletions = 0usize;
    for line in diff.lines() {
        if line.starts_with("diff --git ") {
            if let Some(path) = parse_diff_path(line) {
                files.push(json!({ "path": path }));
            }
        } else if line.starts_with('+') && !line.starts_with("+++") {
            additions += 1;
        } else if line.starts_with('-') && !line.starts_with("---") {
            deletions += 1;
        }
    }
    json!({
        "files": files.len(),
        "additions": additions,
        "deletions": deletions,
        "file_paths": files
    })
}

async fn read_workspace_diff(
    workspace: &str,
    base: &str,
    path_filter: Option<&str>,
) -> Result<String> {
    let mut args = vec!["diff", "--no-color", base];
    if let Some(path) = path_filter {
        args.push("--");
        args.push(path);
    }
    let output = tokio::process::Command::new("git")
        .args(args)
        .current_dir(Path::new(workspace))
        .output()
        .await
        .map_err(|e| tool_message("review_diff", e))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return tool_error("review_diff", format!("git diff failed: {stderr}"));
    }
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

fn parse_diff_lines(diff: &str) -> Vec<(String, usize, &str)> {
    let mut out = Vec::new();
    let mut current = String::new();
    for raw in diff.lines() {
        if raw.starts_with("diff --git ") {
            if let Some(path) = parse_diff_path(raw) {
                current = path;
            }
        }
        if (raw.starts_with('+') && !raw.starts_with("+++"))
            || (raw.starts_with('-') && !raw.starts_with("---"))
        {
            out.push((current.clone(), 0, &raw[1..]));
        }
    }
    out
}

fn parse_diff_path(line: &str) -> Option<String> {
    let rest = line.strip_prefix("diff --git ")?;
    let mut parts = rest.split_whitespace();
    let _a = parts.next()?;
    let b = parts.next()?;
    let path = b.strip_prefix("b/").unwrap_or(b);
    Some(path.to_string())
}

fn resolve_existing(workspace: &str, input: &str, tool: &str) -> Result<PathBuf> {
    let workspace = Path::new(workspace);
    let candidate = Path::new(input);
    let joined = if candidate.is_absolute() {
        candidate.to_path_buf()
    } else {
        workspace.join(candidate)
    };
    let resolved = joined.canonicalize().map_err(|e| tool_message(tool, e))?;
    if !resolved.starts_with(workspace) {
        return tool_error(tool, "path escapes the workspace boundary");
    }
    Ok(resolved)
}

fn path_for_output(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn tool_error<T>(tool: &str, message: impl std::fmt::Display) -> Result<T> {
    Err(tool_message(tool, message))
}

fn tool_message(tool: &str, message: impl std::fmt::Display) -> OdonError {
    OdonError::Tool {
        tool: tool.to_string(),
        message: message.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_unsafe_unwrap_todo_and_secret_patterns() {
        let cases = [
            ("unsafe { ptr::read(src) }", Some(("high", "safety"))),
            ("let x = option.unwrap()", Some(("medium", "robustness"))),
            ("todo!(\"later\")", Some(("medium", "correctness"))),
            ("println!(\"{secret}\")", Some(("critical", "secrets"))),
            ("password = \"hunter2\"", Some(("high", "secrets"))),
        ];
        for (text, expected) in cases {
            let finding = review_line("src/app.rs", 1, text)
                .or_else(|| security_review_line("src/app.rs", 1, text))
                .unwrap();
            assert_eq!(finding.severity, expected.unwrap().0);
            assert_eq!(finding.category, expected.unwrap().1);
        }
    }

    #[test]
    fn summarizes_additions_and_deletions() {
        let diff = "\
diff --git a/src/lib.rs b/src/lib.rs
--- a/src/lib.rs
+++ b/src/lib.rs
@@ -1 +1,2 @@
 fn main() {
+    hello();
 }
";
        let summary = summarize_diff(diff);
        assert_eq!(summary["files"], 1);
        assert_eq!(summary["additions"], 1);
        assert_eq!(summary["deletions"], 0);
    }
}

use crate::registry::{Tool, ToolContext};
use async_trait::async_trait;
use odon_core::error::Result;
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::net::TcpStream;

pub struct DevServerStatusTool;

#[async_trait]
impl Tool for DevServerStatusTool {
    fn name(&self) -> &str {
        "dev_server_status"
    }
    fn description(&self) -> &str {
        "Check whether candidate dev server ports are open and responding"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "host": { "type": "string", "default": "127.0.0.1" },
                "ports": { "type": "array", "items": { "type": "integer", "minimum": 1, "maximum": 65535 } }
            }
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }

    async fn execute(&self, _ctx: &ToolContext, args: Value) -> Result<Value> {
        let host = args
            .get("host")
            .and_then(Value::as_str)
            .unwrap_or("127.0.0.1");
        let ports = args
            .get("ports")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| item.as_u64())
                    .filter(|port| *port > 0 && *port <= 65535)
                    .map(|port| port as u16)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![3000, 5173, 8080, 8000, 4000, 4200, 5000, 8888, 9000]);

        let mut results = Vec::new();
        for port in ports {
            let open = is_port_open(host, port);
            results.push(json!({ "host": host, "port": port, "open": open }));
        }
        Ok(json!({ "host": host, "results": results }))
    }
}

pub struct BrowserStatusTool;

#[async_trait]
impl Tool for BrowserStatusTool {
    fn name(&self) -> &str {
        "browser_status"
    }
    fn description(&self) -> &str {
        "Report available browser automation capabilities on this host"
    }
    fn parameters_schema(&self) -> Value {
        json!({ "type": "object", "properties": {} })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }

    async fn execute(&self, ctx: &ToolContext, _args: Value) -> Result<Value> {
        let has_chrome = has_executable("chrome")
            || has_executable("google-chrome")
            || has_executable("chromium")
            || has_executable("chromium-browser");
        let has_edge = has_executable("msedge");
        let (live_sessions, persisted_sessions) =
            crate::browser_session::session_status_counts(&ctx.workspace_root).await;
        Ok(json!({
            "chrome": has_chrome,
            "edge": has_edge,
            "headless_screenshot": has_chrome || has_edge,
            "persistent_session": persisted_sessions > 0 || live_sessions > 0,
            "live_sessions": live_sessions,
            "persisted_sessions": persisted_sessions,
            "note": if has_chrome || has_edge { "Persistent browser sessions are available via browser_session_create and browser_session_resume." } else { "No Chromium-class browser detected on PATH." }
        }))
    }
}

fn is_port_open(host: &str, port: u16) -> bool {
    TcpStream::connect_timeout(
        &std::net::SocketAddr::new(
            host.parse()
                .unwrap_or(std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)),
            port,
        ),
        std::time::Duration::from_millis(200),
    )
    .is_ok()
}

fn has_executable(name: &str) -> bool {
    std::process::Command::new(name)
        .arg("--version")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

use crate::registry::{Tool, ToolContext};
use odon_core::{OdonError, Result};
use odon_security::RiskTier;
use serde::Deserialize;
use serde_json::json;
use serde_json::Value;
use std::path::{Path, PathBuf};
use std::time::Duration;
use tokio::process::Command;
use tokio::time::timeout;

#[derive(Debug, Deserialize)]
struct SftpUploadPayload {
    profile_id: String,
    local_path: String,
    remote_path: String,
}

#[derive(Debug, Deserialize)]
struct SftpDownloadPayload {
    profile_id: String,
    remote_path: String,
    local_path: String,
}

#[derive(Debug, Deserialize)]
struct SftpListPayload {
    profile_id: String,
    remote_path: String,
}

#[derive(Debug, Deserialize, Clone)]
struct SshProfile {
    id: String,
    alias: String,
    host: String,
    #[serde(default)]
    port: Option<u16>,
    user: String,
    #[serde(default)]
    key_path: Option<String>,
}

struct SshTarget {
    user: String,
    host: String,
    port: Option<u16>,
    key_path: Option<String>,
}

impl SshTarget {
    fn host_target(&self) -> String {
        let host = if self.host.contains(':') && !self.host.starts_with('[') {
            format!("[{}]", self.host)
        } else {
            self.host.clone()
        };
        format!("{}@{}", self.user, host)
    }

    fn base_args(&self) -> Vec<String> {
        let mut args = vec![
            "-o".to_string(),
            "StrictHostKeyChecking=yes".to_string(),
            "-o".to_string(),
            "ConnectTimeout=15".to_string(),
            "-o".to_string(),
            "ServerAliveInterval=10".to_string(),
            "-o".to_string(),
            "BatchMode=yes".to_string(),
        ];
        if let Some(key) = &self.key_path {
            args.push("-i".to_string());
            args.push(key.clone());
        }
        args
    }

    fn ssh_args(&self) -> Vec<String> {
        let mut args = self.base_args();
        if let Some(port) = self.port {
            args.push("-p".to_string());
            args.push(port.to_string());
        }
        args.push(self.host_target());
        args
    }

    fn scp_args(&self) -> Vec<String> {
        let mut args = self.base_args();
        if let Some(port) = self.port {
            args.push("-P".to_string());
            args.push(port.to_string());
        }
        args
    }
}

fn validate_ssh_field(value: &str, label: &str) -> Result<()> {
    if value.trim().is_empty()
        || value.starts_with('-')
        || value.chars().any(|ch| {
            ch.is_whitespace()
                || matches!(
                    ch,
                    '\0' | '\n' | '\r' | '@' | '\'' | '"' | ';' | '|' | '&' | '$' | '`' | '<' | '>'
                )
        })
    {
        return Err(OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("Invalid SSH {label}: {value:?}"),
        });
    }
    Ok(())
}

fn load_ssh_target(profile_id: &str) -> Result<SshTarget> {
    let profiles_path = dirs::home_dir()
        .ok_or_else(|| OdonError::Tool {
            tool: "sftp".to_string(),
            message: "Cannot locate home directory".to_string(),
        })?
        .join(".odon")
        .join("ssh-profiles.json");

    let data = std::fs::read_to_string(&profiles_path).map_err(|e| OdonError::Tool {
        tool: "sftp".to_string(),
        message: format!("Failed to read SSH profiles: {e}"),
    })?;

    let profiles: Vec<SshProfile> = serde_json::from_str(&data).map_err(|e| OdonError::Tool {
        tool: "sftp".to_string(),
        message: format!("Invalid SSH profiles file: {e}"),
    })?;

    let profile = profiles
        .into_iter()
        .find(|p| p.id == profile_id || p.alias == profile_id)
        .ok_or_else(|| OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("SSH profile '{profile_id}' not found"),
        })?;

    validate_ssh_field(&profile.user, "username")?;
    validate_ssh_field(&profile.host, "host")?;
    if let Some(key) = &profile.key_path {
        if key.trim().is_empty() || key.contains(['\0', '\n', '\r']) {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: "Invalid SSH key path".to_string(),
            });
        }
    }

    Ok(SshTarget {
        user: profile.user,
        host: profile.host,
        port: profile.port,
        key_path: profile.key_path,
    })
}

fn normalize_remote_path(path: &str, user: &str) -> Result<String> {
    let path = path.trim();
    if path.is_empty() || path.contains(['\0', '\n', '\r']) {
        return Err(OdonError::Tool {
            tool: "sftp".to_string(),
            message: "Remote path must not be empty or contain control characters".to_string(),
        });
    }
    if path == "~" {
        return Ok(format!("/home/{user}"));
    }
    if let Some(rest) = path.strip_prefix("~/") {
        return Ok(format!("/home/{user}/{rest}"));
    }
    if !path.starts_with('/') {
        return Err(OdonError::Tool {
            tool: "sftp".to_string(),
            message: "Remote path must be absolute or start with '~/'".to_string(),
        });
    }
    Ok(path.to_string())
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn local_workspace_path(ctx: &ToolContext, input: &str, for_write: bool) -> Result<PathBuf> {
    let root = std::path::Path::new(&ctx.workspace_root)
        .canonicalize()
        .map_err(|error| OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("Cannot resolve workspace: {error}"),
        })?;
    let candidate = PathBuf::from(input);
    let joined = if candidate.is_absolute() {
        candidate
    } else {
        root.join(candidate)
    };

    if for_write {
        let parent = joined.parent().unwrap_or(&root);
        // Validate before creating anything. This used to call create_dir_all
        // first and only then check containment, so a path like
        // ../../outside/x created that directory tree outside the workspace
        // and the operation was rejected afterwards - too late.
        let mut ancestor = parent;
        while std::fs::symlink_metadata(ancestor).is_err() {
            let Some(next) = ancestor.parent() else {
                return Err(OdonError::Tool {
                    tool: "sftp".to_string(),
                    message: "Invalid local destination".to_string(),
                });
            };
            ancestor = next;
        }
        let canonical_ancestor = ancestor.canonicalize().map_err(|error| OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("Cannot resolve local destination: {error}"),
        })?;
        if !canonical_ancestor.starts_with(&root) {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: "Local destination is outside the workspace".to_string(),
            });
        }
        std::fs::create_dir_all(parent).map_err(|error| OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("Cannot create local destination: {error}"),
        })?;

        let parent = parent.canonicalize().map_err(|error| OdonError::Tool {
            tool: "sftp".to_string(),
            message: format!("Cannot resolve local destination: {error}"),
        })?;
        if !parent.starts_with(&root) {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: "Local destination is outside the workspace".to_string(),
            });
        }
        return Ok(parent.join(joined.file_name().unwrap_or_default()));
    }

    let canonical = joined.canonicalize().map_err(|error| OdonError::Tool {
        tool: "sftp".to_string(),
        message: format!("Cannot resolve local path: {error}"),
    })?;
    if !canonical.starts_with(&root) {
        return Err(OdonError::Tool {
            tool: "sftp".to_string(),
            message: "Local path is outside the workspace".to_string(),
        });
    }
    Ok(canonical)
}

async fn scp_transfer(
    _ctx: &ToolContext,
    profile_id: &str,
    local: &Path,
    remote: &str,
    to_remote: bool,
) -> Result<Value> {
    let target = load_ssh_target(profile_id)?;
    let remote = normalize_remote_path(remote, &target.user)?;
    let remote_spec = format!("{}:{}", target.host_target(), shell_quote(&remote));

    let mut cmd = Command::new("scp");
    cmd.args(target.scp_args());
    if to_remote {
        cmd.arg(local).arg(&remote_spec);
    } else {
        cmd.arg(&remote_spec).arg(local);
    }

    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let execution = timeout(Duration::from_secs(120), cmd.output()).await;
    let output = match execution {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: format!("scp execution failed: {e}"),
            });
        }
        Err(_) => {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: "scp timed out after 120 seconds".to_string(),
            });
        }
    };

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();

    const MAX_OUTPUT_BYTES: usize = 1_048_576;
    let mut capped_stdout = stdout;
    let mut capped_stderr = stderr;
    let mut truncated = false;
    if capped_stdout.len() > MAX_OUTPUT_BYTES {
        capped_stdout.truncate(MAX_OUTPUT_BYTES);
        truncated = true;
    }
    if capped_stderr.len() > MAX_OUTPUT_BYTES {
        capped_stderr.truncate(MAX_OUTPUT_BYTES);
        truncated = true;
    }
    if truncated {
        capped_stderr.push_str("\n[ODON] output capped at 1 MB");
    }

    Ok(json!({
        "success": output.status.success(),
        "exit_code": output.status.code().unwrap_or(-1),
        "stdout": capped_stdout,
        "stderr": capped_stderr,
        "local_path": local.to_string_lossy(),
        "remote_path": remote,
    }))
}

async fn ssh_list(_ctx: &ToolContext, profile_id: &str, remote_path: &str) -> Result<Value> {
    let target = load_ssh_target(profile_id)?;
    let remote = normalize_remote_path(remote_path, &target.user)?;
    let mut cmd = Command::new("ssh");
    cmd.args(target.ssh_args());
    cmd.arg(format!("ls -la -- {}", shell_quote(&remote)));

    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::piped());

    let execution = timeout(Duration::from_secs(30), cmd.output()).await;
    let output = match execution {
        Ok(Ok(output)) => output,
        Ok(Err(e)) => {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: format!("ssh execution failed: {e}"),
            });
        }
        Err(_) => {
            return Err(OdonError::Tool {
                tool: "sftp".to_string(),
                message: "ssh timed out after 30 seconds".to_string(),
            });
        }
    };

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();

    const MAX_OUTPUT_BYTES: usize = 1_048_576;
    let mut capped_stdout = stdout;
    let mut capped_stderr = stderr;
    let mut truncated = false;
    if capped_stdout.len() > MAX_OUTPUT_BYTES {
        capped_stdout.truncate(MAX_OUTPUT_BYTES);
        truncated = true;
    }
    if capped_stderr.len() > MAX_OUTPUT_BYTES {
        capped_stderr.truncate(MAX_OUTPUT_BYTES);
        truncated = true;
    }
    if truncated {
        capped_stderr.push_str("\n[ODON] output capped at 1 MB");
    }

    Ok(json!({
        "success": output.status.success(),
        "exit_code": output.status.code().unwrap_or(-1),
        "remote_path": remote_path,
        "listing": capped_stdout,
        "stderr": capped_stderr,
    }))
}

