            .args(["-9", &task.pid.to_string()])
            .output()
            .await;

        let killed = output
            .map(|result| result.status.success())
            .unwrap_or(false);
        Ok(json!({ "task_id": task_id, "pid": task.pid, "killed": killed }))
    }
