//! Minimal, allocation-friendly unified diff used to render edit boxes in chat.
//!
//! The generator trims the common prefix and suffix of the two texts, then
//! renders the changed middle as a single hunk with three lines of context.
//! That keeps the cost linear in the file size (no O(n*m) LCS table), which
//! matters because every edit an agent makes is diffed on the request path.

const CONTEXT: usize = 3;

pub struct UnifiedDiff {
    pub text: String,
    pub additions: usize,
    pub deletions: usize,
}

/// Build a unified diff for `before` → `after`, or `None` when nothing changed.
pub fn unified_diff(path: &str, before: &str, after: &str) -> Option<UnifiedDiff> {
    if before == after {
        return None;
    }

    let old: Vec<&str> = split_lines(before);
    let new: Vec<&str> = split_lines(after);

    let mut prefix = 0;
    while prefix < old.len() && prefix < new.len() && old[prefix] == new[prefix] {
        prefix += 1;
    }

    let mut suffix = 0;
    while suffix < old.len() - prefix
        && suffix < new.len() - prefix
        && old[old.len() - 1 - suffix] == new[new.len() - 1 - suffix]
    {
        suffix += 1;
    }

    let old_mid = &old[prefix..old.len() - suffix];
    let new_mid = &new[prefix..new.len() - suffix];

    let ctx_start = prefix.saturating_sub(CONTEXT);
    let old_tail = (suffix).min(CONTEXT);
    let new_tail = (suffix).min(CONTEXT);

    let old_span = prefix - ctx_start + old_mid.len() + old_tail;
    let new_span = prefix - ctx_start + new_mid.len() + new_tail;

    // Unified diff hunk numbering is 1-based; an empty span at the start of a
    // new file is written as "0,0" by convention.
    let old_first = if old_span == 0 { 0 } else { ctx_start + 1 };
    let new_first = if new_span == 0 { 0 } else { ctx_start + 1 };

    let mut text = String::with_capacity(64 + (old_span + new_span) * 32);
    text.push_str(&format!("--- a/{path}\n"));
    text.push_str(&format!("+++ b/{path}\n"));
    text.push_str(&format!(
        "@@ -{old_first},{old_span} +{new_first},{new_span} @@\n"
    ));

    for line in &old[ctx_start..prefix] {
        push_line(&mut text, ' ', line);
    }
    for line in old_mid {
        push_line(&mut text, '-', line);
    }
    for line in new_mid {
        push_line(&mut text, '+', line);
    }
    for line in &old[old.len() - suffix..old.len() - suffix + old_tail] {
        push_line(&mut text, ' ', line);
    }

    Some(UnifiedDiff {
        text,
        additions: if new_mid.is_empty() { 0 } else { new_mid.len() },
        deletions: if old_mid.is_empty() { 0 } else { old_mid.len() },
    })
}

fn push_line(out: &mut String, marker: char, line: &str) {
    out.push(marker);
    out.push_str(line);
    out.push('\n');
}

/// Split into lines without a trailing empty entry, so a file ending in a
/// newline does not report a spurious changed last line.
fn split_lines(text: &str) -> Vec<&str> {
    if text.is_empty() {
        return Vec::new();
    }
    let trimmed = text.strip_suffix('\n').unwrap_or(text);
    trimmed.split('\n').collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unchanged_text_produces_no_diff() {
        assert!(unified_diff("src/a.rs", "same\n", "same\n").is_none());
    }

    #[test]
    fn counts_additions_and_deletions() {
        let d = unified_diff("src/a.rs", "a\nb\nc\n", "a\nB\nc\n").expect("diff");
        assert_eq!(d.additions, 1);
        assert_eq!(d.deletions, 1);
        assert!(d.text.contains("-b"));
        assert!(d.text.contains("+B"));
        assert!(d.text.contains("--- a/src/a.rs"));
        assert!(d.text.contains("+++ b/src/a.rs"));
    }

    #[test]
    fn pure_addition_has_no_deletions() {
        let d = unified_diff("f", "a\n", "a\nb\n").expect("diff");
        assert_eq!(d.additions, 1);
        assert_eq!(d.deletions, 0);
    }

    #[test]
    fn pure_deletion_has_no_additions() {
        let d = unified_diff("f", "a\nb\n", "a\n").expect("diff");
        assert_eq!(d.additions, 0);
        assert_eq!(d.deletions, 1);
    }

    #[test]
    fn creates_file_from_empty() {
        let d = unified_diff("new.txt", "", "hello\n").expect("diff");
        assert_eq!(d.additions, 1);
        assert_eq!(d.deletions, 0);
        assert!(d.text.contains("+hello"));
    }

    #[test]
    fn context_lines_are_included() {
        let before = "1\n2\n3\n4\n5\n6\n7\n8\n9\n";
        let after = "1\n2\n3\nX\n5\n6\n7\n8\n9\n";
        let d = unified_diff("f", before, after).expect("diff");
        // three context lines above and below the change; line "4" is the
        // changed line itself, so it renders as "-4" rather than context.
        assert!(d.text.contains(" 2\n"));
        assert!(d.text.contains(" 3\n"));
        assert!(d.text.contains("-4\n"));
        assert!(d.text.contains(" 5\n"));
        assert!(d.text.contains(" 6\n"));
        assert!(d.text.contains("+X"));
    }

    #[test]

    fn output_stays_linear_for_large_files() {
        let before: String = (0..20_000).map(|i| format!("line {i}\n")).collect();
        let mut after = before.clone();
        after.push_str("appended\n");
        let d = unified_diff("big.txt", &before, &after).expect("diff");
        assert_eq!(d.additions, 1);
        assert_eq!(d.deletions, 0);
        assert!(d.text.len() < 4_000, "diff should stay small: {}", d.text.len());
    }
}

use async_trait::async_trait;
use odon_core::{OdonError, Result};
use odon_security::RiskTier;
use serde_json::{json, Value};
use std::net::{IpAddr, SocketAddr};
use tracing::info;

use crate::net_guard;
use crate::registry::{Tool, ToolContext};

/// DoH (DNS-over-HTTPS) resolver to bypass ISP blocking/DNS poisoning (e.g. DDG blocking in ID).
pub async fn doh_resolve_host(host: &str) -> Option<IpAddr> {
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(4))
        .build()
        .ok()?;

    // 1. Try Cloudflare DoH (JSON API)
    let cf_url = format!(
        "https://cloudflare-dns.com/dns-query?name={}&type=A",
        urlencoding::encode(host)
    );
    if let Ok(res) = client
        .get(&cf_url)
        .header("accept", "application/dns-json")
        .send()
        .await
    {
        if res.status().is_success() {
            if let Ok(val) = res.json::<Value>().await {
                if let Some(answers) = val.get("Answer").and_then(|a| a.as_array()) {
                    for ans in answers {
                        if let Some(ip_str) = ans.get("data").and_then(|d| d.as_str()) {
                            if let Ok(ip) = ip_str.parse::<IpAddr>() {
                                return Some(ip);
                            }
                        }
                    }
                }
            }
        }
    }

    // 2. Try Google DoH (JSON API)
    let google_url = format!(
        "https://dns.google/resolve?name={}&type=A",
        urlencoding::encode(host)
    );
    if let Ok(res) = client
        .get(&google_url)
        .header("accept", "application/json")
        .send()
        .await
    {
        if res.status().is_success() {
            if let Ok(val) = res.json::<Value>().await {
                if let Some(answers) = val.get("Answer").and_then(|a| a.as_array()) {
                    for ans in answers {
                        if let Some(ip_str) = ans.get("data").and_then(|d| d.as_str()) {
                            if let Ok(ip) = ip_str.parse::<IpAddr>() {
                                return Some(ip);
                            }
                        }
                    }
                }
            }
        }
    }

    None
}

fn decode_ddg_url(raw: &str) -> String {
    if let Some(idx) = raw.find("uddg=") {
        let after = &raw[idx + 5..];
        let end = after.find('&').unwrap_or(after.len());
        let slice = &after[..end];
        let decoded = url::form_urlencoded::parse(format!("u={}", slice).as_bytes())
            .find(|(k, _)| k == "u")
            .map(|(_, v)| v.into_owned())
            .unwrap_or_else(|| slice.to_string());
        return decoded;
    }
    if raw.starts_with("//") {
        return format!("https:{}", raw);
    }
    raw.to_string()
}

pub fn clean_html_snippet(raw: &str) -> String {
    // Strip non-visible blocks before removing tags; otherwise CSS and JS text
    // leaks into the "readable" page sent to the agent.
    let mut visible = raw.to_string();
    for pattern in [
        r"(?is)<script[^>]*>.*?</script>",
        r"(?is)<style[^>]*>.*?</style>",
        r"(?is)<noscript[^>]*>.*?</noscript>",
        r"(?is)<svg[^>]*>.*?</svg>",
        r"(?is)<!--.*?-->",
    ] {
        if let Ok(re) = regex::Regex::new(pattern) {
            visible = re.replace_all(&visible, " ").to_string();
        }
    }
    let re = regex::Regex::new(r"<[^>]+>").ok();
    let text = if let Some(r) = re {
        r.replace_all(&visible, " ").to_string()
    } else {
        visible
    };
    text.replace("&amp;", "&")
        .replace("&quot;", "\"")
        .replace("&#x27;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

pub struct WebSearchTool;

#[async_trait]
impl Tool for WebSearchTool {
    fn name(&self) -> &str {
        "web_search"
    }
    fn description(&self) -> &str {
        "Search the web for up-to-date documentation, news, or technical answers"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": { "type": "string", "description": "Search query or question" },
                "limit": { "type": "integer", "description": "Maximum number of search results (default 5)" }
            },
            "required": ["query"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, _ctx: &ToolContext, args: Value) -> Result<Value> {
        let query = args
            .get("query")
            .and_then(|q| q.as_str())
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: "Missing 'query' parameter".to_string(),
            })?;
        let limit = args.get("limit").and_then(|l| l.as_u64()).unwrap_or(5) as usize;

info!("Executing web search for: {}", query);

// 1. Attempt DuckDuckGo HTML using DoH resolved IP to bypass ISP blocking
let ddg_ip = doh_resolve_host("html.duckduckgo.com").await;
let mut client_builder = reqwest::Client::builder()
    .timeout(std::time::Duration::from_secs(8))
    .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36");

if let Some(ip) = ddg_ip {
    client_builder =
        client_builder.resolve("html.duckduckgo.com", SocketAddr::new(ip, 443));
}
let client = client_builder
    .build()
    .unwrap_or_else(|_| reqwest::Client::new());

let url = format!(
    "https://html.duckduckgo.com/html/?q={}",
    urlencoding::encode(query)
);
let resp = client
    .get(&url)
    .header(
        "Accept",
        "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    )
    .header("Accept-Language", "en-US,en;q=0.9,id;q=0.8")
    .send()
    .await;

let mut results = Vec::new();

if let Ok(response) = resp {
    if let Ok(html) = response.text().await {
        let snippet_re =
            regex::Regex::new(r#"<a class="result__snippet[^>]*>([\s\S]*?)</a>"#).ok();
        let link_re = regex::Regex::new(
            r#"<a class="result__url[^>]*href="([^"]+)"[^>]*>([\s\S]*?)</a>"#,
        )
        .ok();

        if let (Some(s_re), Some(l_re)) = (snippet_re, link_re) {
            let links: Vec<_> = l_re.captures_iter(&html).take(limit).collect();
            let snippets: Vec<_> = s_re.captures_iter(&html).take(limit).collect();

            for (i, l_cap) in links.iter().enumerate() {
                let raw_link = l_cap.get(1).map(|m| m.as_str().trim()).unwrap_or("");
                let title = clean_html_snippet(
                    l_cap.get(2).map(|m| m.as_str().trim()).unwrap_or("Result"),
                );
                let snippet = snippets
                    .get(i)
                    .and_then(|s| s.get(1))
                    .map(|m| clean_html_snippet(m.as_str().trim()))
                    .unwrap_or_default();
                let link = decode_ddg_url(raw_link);

                if !link.is_empty() {
                    results.push(json!({
                        "title": title,
                        "url": link,
                        "snippet": snippet,
                        "source": "duckduckgo"
                    }));
                }
            }
        }
    }
}

// 2. Fallback to Wikipedia OpenSearch API if DDG HTML was empty or blocked
if results.is_empty() {
    let wiki_url = format!(
        "https://en.wikipedia.org/w/api.php?action=opensearch&search={}&limit={}&namespace=0&format=json",
        urlencoding::encode(query),
        limit
    );
    if let Ok(wiki_res) = client.get(&wiki_url).send().await {
        if let Ok(val) = wiki_res.json::<Value>().await {
            if let Some(arr) = val.as_array() {
                if arr.len() >= 4 {
                    let titles = arr[1].as_array();
                    let snippets = arr[2].as_array();
                    let urls = arr[3].as_array();
                    if let (Some(t_arr), Some(s_arr), Some(u_arr)) =
                        (titles, snippets, urls)
                    {
                        for i in 0..t_arr.len() {
                            let t = t_arr.get(i).and_then(|x| x.as_str()).unwrap_or("");
                            let s = s_arr.get(i).and_then(|x| x.as_str()).unwrap_or("");
                            let u = u_arr.get(i).and_then(|x| x.as_str()).unwrap_or("");
                            if !u.is_empty() {
                                results.push(json!({
                                    "title": t,
                                    "url": u,
                                    "snippet": s,
                                    "source": "wikipedia"
                                }));
                            }
                        }
                    }
                }
            }
        }
    }
}

// 3. Fallback to HackerNews Algolia API, but only for technical
// queries. HN is a developer forum: for a weather, address or phone
// lookup it returns unrelated stories, which reads to the model as
// "search is broken" instead of "this source has nothing".
if results.is_empty() && looks_technical(query) {
    let hn_url = format!(
        "https://hn.algolia.com/api/v1/search?query={}&tags=story&hitsPerPage={}",
        urlencoding::encode(query),
        limit
    );
    if let Ok(hn_res) = client.get(&hn_url).send().await {
        if let Ok(val) = hn_res.json::<Value>().await {
            if let Some(hits) = val.get("hits").and_then(|h| h.as_array()) {
                for hit in hits {
                    let title = hit.get("title").and_then(|t| t.as_str()).unwrap_or("");
                    let url = hit.get("url").and_then(|u| u.as_str()).unwrap_or("");
                    let author = hit.get("author").and_then(|a| a.as_str()).unwrap_or("");
                    let points = hit.get("points").and_then(|p| p.as_i64()).unwrap_or(0);
                    if !title.is_empty() {
                        results.push(json!({
                            "title": title,
                            "url": if url.is_empty() { format!("https://news.ycombinator.com/item?id={}", hit.get("objectID").and_then(|o| o.as_str()).unwrap_or("")) } else { url.to_string() },
                            "snippet": format!("Posted by {} ({} points)", author, points),
                            "source": "hackernews"
                        }));
                    }
                }
            }
        }
    }
}

        let mut payload = json!({
            "query": query,
            "results_count": results.len(),
            "results": results
        });
        if payload["results_count"] == json!(0) {
            payload["note"] = json!(concat!(
                "no result from DuckDuckGo, Wikipedia or HackerNews. ",
                "This source set has no general web index; for a live value ",
                "such as weather, a place or a phone number, fetch a site that ",
                "publishes it with web_fetch instead of repeating the search."
            ));
        }
        Ok(payload)
    }
}

/// A query is treated as technical only when it carries a programming or
/// infrastructure token. Everything else gets the honest "no results" note
/// rather than forum noise.
fn looks_technical(query: &str) -> bool {
    const MARKERS: [&str; 24] = [
        "rust",
        "python",
        "javascript",
        "typescript",
        "golang",
        "java",
        "docker",
        "kubernetes",
        "linux",
        "sql",
        "regex",
        "api",
        "npm",
        "cargo",
        "git",
        "http",
        "json",
        "async",
        "compiler",
        "kernel",
        "database",
        "server",
        "framework",
        "library",
    ];
    let lower = query.to_lowercase();
    MARKERS.iter().any(|marker| lower.contains(marker))
}

pub struct WebFetchTool;

#[async_trait]
impl Tool for WebFetchTool {
    fn name(&self) -> &str {
        "web_fetch"
    }
    fn description(&self) -> &str {
        "Fetch the plain text content of a web page URL (with automatic DoH resolution fallback)"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "url": { "type": "string", "description": "Full URL to fetch (https://...)" }
            },
            "required": ["url"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }

async fn execute(&self, _ctx: &ToolContext, args: Value) -> Result<Value> {
    let url_str = args
        .get("url")
        .and_then(|u| u.as_str())
        .ok_or_else(|| OdonError::Tool {
            tool: self.name().to_string(),
            message: "Missing 'url' parameter".to_string(),
        })?;

    let validated = net_guard::validate_url(url_str).await?;
    let url_str = validated.as_str();
    let host = validated.host_str().unwrap_or("").to_string();
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(12))
        .redirect(net_guard::redirect_policy(host.clone()))
        .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36")
        .build()
        .unwrap_or_else(|_| reqwest::Client::new());

    let resp_res = client.get(url_str).send().await;

    let resp = match resp_res {
        Ok(r) => Ok(r),
        Err(e) => {
            // If failed due to DNS resolution error or connect error, attempt DoH fallback
            let parsed_url = reqwest::Url::parse(url_str).ok();
            if let Some(u) = parsed_url {
                if let Some(host) = u.host_str() {
                    let port = u.port().unwrap_or(if u.scheme() == "https" { 443 } else { 80 });
                    if let Some(ip) = doh_resolve_host(host).await {
                        if !net_guard::allow_private_network() && net_guard::is_blocked_ip(ip) {
                            return Err(OdonError::Tool {
                                tool: self.name().to_string(),
                                message: format!("DoH resolved {host} to a private address ({ip}); request blocked"),
                            });
                        }
                        if let Ok(doh_client) = reqwest::Client::builder()
                            .timeout(std::time::Duration::from_secs(12))
                            .redirect(net_guard::redirect_policy(host.to_string()))
                            .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36")
                            .resolve(host, SocketAddr::new(ip, port))
                            .build()
                        {
                            doh_client.get(url_str).send().await
                        } else {
                            Err(e)
                        }
                    } else {
                        Err(e)
                    }
                } else {
                    Err(e)
                }
            } else {
                Err(e)
            }
        }
    }.map_err(|e| OdonError::Tool {
        tool: self.name().to_string(),
        message: format!("Failed to fetch URL {}: {}", url_str, e),
    })?;

    let status = resp.status().as_u16();
    let body = resp.text().await.unwrap_or_default();

    // Extract <title> if present
    let title_re = regex::Regex::new(r#"(?i)<title[^>]*>([^<]+)</title>"#).ok();
    let page_title = title_re
        .as_ref()
        .and_then(|r| r.captures(&body))
        .and_then(|c| c.get(1))
        .map(|m| m.as_str().trim().to_string())
        .unwrap_or_default();

        let clean_text = clean_html_snippet(&body);
        let truncated = if clean_text.len() > 10000 {
            // Snap to a char boundary: arbitrary web text can split a
            // multi-byte UTF-8 character at byte 10000.
            let mut end = 10000;
            while end > 0 && !clean_text.is_char_boundary(end) {
                end -= 1;
            }
            format!("{}... [truncated]", &clean_text[..end])
        } else {
            clean_text
        };

        Ok(json!({
            "url": url_str,
            "status": status,
            "title": page_title,
            "content": truncated
        }))
    }
}

pub struct ProbeUrlTool;

#[async_trait]
impl Tool for ProbeUrlTool {
    fn name(&self) -> &str {
        "probe_url"
    }
    fn description(&self) -> &str {
        "Probe a URL for HTTP status, response headers, and latency"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "url": { "type": "string", "description": "URL to probe" }
            },
            "required": ["url"]
        })
    }
    fn risk_tier(&self) -> RiskTier {
        RiskTier::Tier0ReadOnly
    }
    async fn execute(&self, _ctx: &ToolContext, args: Value) -> Result<Value> {
        let url_str = args
            .get("url")
            .and_then(|u| u.as_str())
            .ok_or_else(|| OdonError::Tool {
                tool: self.name().to_string(),
                message: "Missing 'url' parameter".to_string(),
            })?;

        let validated = net_guard::validate_url(url_str).await?;
        let url_str = validated.as_str();
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(6))
            .redirect(net_guard::redirect_policy(
                validated.host_str().unwrap_or("").to_string(),
            ))
            .build()
            .unwrap_or_else(|_| reqwest::Client::new());

        let start = std::time::Instant::now();
        let resp = client
            .head(url_str)
            .send()
            .await
            .map_err(|e| OdonError::Tool {
                tool: self.name().to_string(),
                message: format!("Probe error on {}: {}", url_str, e),
            })?;

        let elapsed = start.elapsed().as_millis();
        let status = resp.status().as_u16();
        let headers: serde_json::Map<String, Value> = resp
            .headers()
            .iter()
            .map(|(k, v)| (k.to_string(), json!(v.to_str().unwrap_or(""))))
            .collect();

        Ok(json!({
            "url": url_str,
            "status": status,
            "latency_ms": elapsed,
            "headers": headers
        }))
    }
}

