// The composer exposes exactly four modes. Values outside this set are never
// valid UI state: older builds wrote starter-card modes ("create", "agents",
// "automations") into localStorage, so anything unrecognised falls back to chat.
type ExecutionMode = 'chat' | 'auto' | 'agent' | 'plan';

const EXECUTION_MODES: readonly ExecutionMode[] = ['chat', 'auto', 'agent', 'plan'];

function parseExecutionMode(raw: string | null): ExecutionMode {
  if (raw && (EXECUTION_MODES as readonly string[]).includes(raw)) {
    return raw as ExecutionMode;
  }
  return 'chat';
}

interface ToolCallSummary {
  name: string;
  /** Target URL when the tool was called with one, so the chip can open the real page. */
  url?: string;
}

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  showAppCard?: boolean;
  thought?: string;
  toolCalls?: ToolCallSummary[];
  terminal?: TerminalEntry[];
  attachments?: MessageAttachment[];
}

function formatSessionTimestamp(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

// Terminal commands an assistant turn actually ran, taken from the persisted
// tool calls so the chat can show a peek of the real output (never a mock).
function terminalEntriesOf(messages: Message[]): TerminalEntry[] {
  const entries: TerminalEntry[] = [];
  for (const message of messages) {
    for (const call of message.content.tool_calls || []) {
      if (!isTerminalTool(call.tool_name)) continue;
      const cmd = commandOf(call.arguments);
      const output = outputToText(call.output);
      if (!cmd && !output) continue;
      entries.push({ cmd, output, isError: Boolean(call.is_error) });
    }
  }
  return entries.slice(-6);
}

// Persisted agent history contains intermediate assistant/tool records required
// by model providers. Rebuild the user-facing transcript so reopening a session
// shows the same coherent prompt/response flow as the live chat instead of raw
// tool JSON and partial streaming steps.
function normalizeSessionHistory(history: Message[]): ChatMessage[] {
  const output: ChatMessage[] = [];
  let currentUser: Message | null = null;
  let currentAssistants: Message[] = [];

  const flushTurn = () => {
    if (currentUser) {
      output.push({
        id: currentUser.id,
        role: 'user',
        content: currentUser.content.text,
        timestamp: formatSessionTimestamp(currentUser.created_at),
        attachments: currentUser.content.attachments || [],
      });
    }

    const assistants = currentAssistants.filter((message) => message.role === 'assistant');
    const finalAssistant = [...assistants]
      .reverse()
      .find((message) => message.content.text.trim().length > 0);

    if (finalAssistant) {
      const toolCalls: ToolCallSummary[] = Array.from(
        new Map(
          assistants
            .flatMap((message) => message.content.tool_calls || [])
            .map((call) => [
              call.tool_name,
              {
                name: call.tool_name,
                url:
                  typeof (call.arguments as any)?.url === 'string'
                    ? (call.arguments as any).url
                    : undefined,
              } satisfies ToolCallSummary,
            ]),
        ).values(),
      );

      output.push({
        id: finalAssistant.id,
        role: 'assistant',
        content: finalAssistant.content.text,
        timestamp: formatSessionTimestamp(finalAssistant.created_at),
        showAppCard:
          (finalAssistant.content.artifact_ids?.length || 0) > 0 ||
          finalAssistant.content.text.includes('```') ||
          toolCalls.length > 0,
        thought: finalAssistant.content.thought,
        toolCalls,
        terminal: terminalEntriesOf(currentAssistants),
        attachments: finalAssistant.content.attachments || [],
      });
    }

    currentUser = null;
    currentAssistants = [];
  };

  for (const message of history) {
    if (message.role === 'user') {
      flushTurn();
      currentUser = message;
      currentAssistants = [];
    } else if (message.role === 'assistant') {
      currentAssistants.push(message);
    }
    // System and tool records are provider-protocol details, not chat bubbles.
  }

  flushTurn();
  return output;
}

interface SteerCard {
  id: string;
  text: string;
  priority: boolean;
