interface AutomationJob {
  id: string;
  name: string;
  description: string;
  trigger_type: string;
  trigger_value: string;
  prompt: string;
  model: string;
  enabled: boolean;
  last_run: string | null;
  last_status: string | null;
  created_at: string;
  retry_count?: number;
  retry_delay_secs?: number;
  depends_on?: string[];
}

interface AutomationLog {
  id: string;
  automation_id: string;
  automation_name: string;
  triggered_at: string;
  completed_at: string | null;
  status: string;
  output: string;
  attempts?: number;
  error?: string | null;
}

export const AutomationsView: React.FC = () => {
  const [jobs, setJobs] = useState<AutomationJob[]>([]);
  const [logs, setLogs] = useState<AutomationLog[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [runningJobId, setRunningJobId] = useState<string | null>(null);
  const [isCreateOpen, setIsCreateOpen] = useState<boolean>(false);
  const [expandedLogId, setExpandedLogId] = useState<string | null>(null);

  // New Job form state
  const [name, setName] = useState<string>('');
  const [description, setDescription] = useState<string>('');
  const [triggerType, setTriggerType] = useState<string>('cron');
  const [triggerValue, setTriggerValue] = useState<string>('0 8 * * *');
  const [prompt, setPrompt] = useState<string>('');
  const [model, setModel] = useState<string>('odon-auto');
  const [retryCount, setRetryCount] = useState<number>(0);
  const [retryDelay, setRetryDelay] = useState<number>(30);
  const [dependsOn, setDependsOn] = useState<string>('');

const loadData = async () => {
  setIsLoading(true);
  try {
    const [jobsData, logsData] = await Promise.all([
      api.getAutomations(),
      api.getAutomationLogs(),
    ]);
    setJobs(Array.isArray(jobsData) ? jobsData : []);
    setLogs(Array.isArray(logsData) ? logsData : []);
  } catch (err) {
    console.error('Failed to load automations:', err);
  } finally {
    setIsLoading(false);
  }
};

useEffect(() => {
  loadData();
  const interval = setInterval(loadData, 10000);
  return () => clearInterval(interval);
}, []);

const handleToggle = async (job: AutomationJob) => {
  const updated = { ...job, enabled: !job.enabled };
  try {
    await api.saveAutomation(updated);
    setJobs((prev) => prev.map((j) => (j.id === job.id ? updated : j)));
  } catch (err) {
    console.error('Failed to toggle automation:', err);
  }
};

const handleRunNow = async (id: string) => {
  setRunningJobId(id);
  try {
    await api.triggerAutomation(id);
    setTimeout(() => {
      setRunningJobId(null);
      loadData();
    }, 1500);
  } catch (err) {
    console.error('Failed to trigger automation:', err);
    setRunningJobId(null);
  }
};

const handleDelete = async (id: string) => {
  try {
    await api.deleteAutomation(id);
    setJobs((prev) => prev.filter((j) => j.id !== id));
  } catch (err) {
    console.error('Failed to delete automation:', err);
  }
};

const handleCreateSubmit = async (e: React.FormEvent) => {
  e.preventDefault();
  if (!name.trim() || !prompt.trim()) return;

  const newJob: AutomationJob = {
    id: `job-${Date.now()}`,
    name: name.trim(),
    description: description.trim(),
    trigger_type: triggerType,
    trigger_value: triggerValue,
    prompt: prompt.trim(),
    model,
    enabled: true,
    last_run: null,
    last_status: null,
    created_at: new Date().toISOString().split('T')[0],
    retry_count: Number(retryCount) || 0,
    retry_delay_secs: Number(retryDelay) || 30,
    depends_on: dependsOn
      .split(',')
      .map((value) => value.trim())
      .filter(Boolean),
  };

  try {
    await api.saveAutomation(newJob);
    setJobs((prev) => [newJob, ...prev]);
    setIsCreateOpen(false);
    setName('');
    setDescription('');
    setPrompt('');
  } catch (err) {
    console.error('Failed to save automation:', err);
  }
};

