import { useMemo, useState } from 'react';
import { ChevronDown, ChevronRight, SquareTerminal, ArrowUpRight } from 'lucide-react';

export interface TerminalEntry {
  cmd: string;
  output: string;
  isError: boolean;
}

const MAX_PREVIEW_LINES = 8;

/** Terminal tools whose output is worth peeking at inside the transcript. */
export const TERMINAL_TOOL_NAMES = [
  'terminal_exec',
  'bash_run',
  'shell_exec',
  'exec_background',
  'exec_stream_stdout',
  'ssh_exec',
  'dev_server_start',
];

export function isTerminalTool(name: string): boolean {
  return TERMINAL_TOOL_NAMES.includes(name);
}

/** Turn an arbitrary tool output value into readable terminal text. */
export function outputToText(output: unknown): string {
  if (output == null) return '';
  if (typeof output === 'string') return output;
  if (typeof output === 'object') {
    const rec = output as Record<string, unknown>;
    for (const key of ['stdout', 'output', 'text', 'result', 'content']) {
      const v = rec[key];
      if (typeof v === 'string' && v.trim()) {
        const stderr = typeof rec.stderr === 'string' ? rec.stderr : '';
        return stderr ? `${v}\n${stderr}` : v;
      }
    }
    try {
      return JSON.stringify(output, null, 2);
    } catch {
      return String(output);
    }
  }
  return String(output);
}

export function commandOf(args: unknown): string {
  if (!args || typeof args !== 'object') return '';
  const rec = args as Record<string, unknown>;
  for (const key of ['command', 'cmd', 'command_line', 'script']) {
    const v = rec[key];
    if (typeof v === 'string') return v;
  }
  return '';
}

export interface TerminalPeekProps {
  entries: TerminalEntry[];
  onOpenTerminal?: () => void;
  dense?: boolean;
}

/**
 * Compact terminal peek shown inside the chat stream: the command the agent ran
 * and the tail of its real output, with a jump to the full terminal panel.
 */
export function TerminalPeek({ entries, onOpenTerminal, dense = false }: TerminalPeekProps) {
  const [expanded, setExpanded] = useState(false);
  const last = entries[entries.length - 1];
  const totals = useMemo(() => {
    const lines = entries.reduce((acc, e) => acc + e.output.split('\n').length, 0);
    return { lines, failed: entries.filter((e) => e.isError).length };
  }, [entries]);

  if (!last) return null;

  const visible = entries.slice(expanded ? -4 : -1);
  const tail = (text: string) => {
    const lines = text.split('\n').filter((l, i, arr) => !(i === arr.length - 1 && l === ''));
    return expanded ? lines.slice(-40) : lines.slice(-MAX_PREVIEW_LINES);
  };

  return (
    <div className={`${dense ? 'my-1.5' : 'my-2'} rounded-xl overflow-hidden border border-neutral-300 bg-[#22211e] text-[#e8e4da] font-mono text-[11px] shadow-2xs`}>
      <div className="flex items-center justify-between gap-2 px-2.5 py-1.5 bg-[#2c2b27] border-b border-neutral-700">
        <div className="flex items-center gap-1.5 min-w-0">
          <SquareTerminal className="w-3 h-3 shrink-0 text-[#a9c3b3]" />
          <span className="truncate text-[#d8d3c6]" title={last.cmd}>
            {last.cmd || 'terminal'}
          </span>
        </div>
        <div className="flex items-center gap-1.5 shrink-0">
          {entries.length > 1 && (
            <span className="text-[10px] text-[#8f897a]">{entries.length} cmds</span>
          )}
          {totals.failed > 0 && (
            <span className="text-[10px] text-[#d99a8a]">{totals.failed} failed</span>
          )}
          <button
            onClick={() => setExpanded((v) => !v)}
            className="flex items-center gap-0.5 rounded px-1 py-0.5 text-[#b9b3a5] hover:bg-[#3a3934] transition-colors cursor-pointer"
            title={expanded ? 'Collapse terminal peek' : `Expand (${totals.lines} lines)`}
          >
            {expanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
            <span className="text-[10px]">{totals.lines}</span>
          </button>
          {onOpenTerminal && (
            <button
              onClick={onOpenTerminal}
              className="flex items-center gap-0.5 rounded px-1 py-0.5 text-[#b9b3a5] hover:bg-[#3a3934] transition-colors cursor-pointer"
              title="Open the full terminal panel"
            >
              <ArrowUpRight className="w-3 h-3" />
            </button>
          )}
        </div>
      </div>

      <div className={`px-2.5 py-1.5 ${expanded ? 'max-h-72' : 'max-h-24'} overflow-y-auto scrollbar-thin`}>
        {visible.map((entry, i) => {
          const lines = tail(entry.output);
          const hidden = expanded ? 0 : entry.output.split('\n').length - lines.length;
          return (
            <div key={i} className={i > 0 ? 'mt-2 pt-2 border-t border-neutral-700/70' : ''}>
              {expanded && entries.length > 1 && (
                <div className="text-[10px] text-[#8f897a] truncate mb-0.5">$ {entry.cmd || '(no command)'}</div>
              )}
              <pre className={`whitespace-pre-wrap break-words ${entry.isError ? 'text-[#e3a99b]' : 'text-[#d5d1c6]'}`}>
                {lines.join('\n') || '(no output)'}
              </pre>
              {hidden > 0 && (
                <button
                  onClick={() => setExpanded(true)}
                  className="mt-0.5 text-[10px] text-[#9aa79d] hover:text-[#c8d3c9] cursor-pointer"
                >
                  +{hidden} more line{hidden === 1 ? '' : 's'}
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import {
  Terminal as TerminalIcon,
  RotateCcw,
  Copy,
  Check,
  Plus,
  X,
  ChevronDown,
  Command,
} from 'lucide-react';
import { NativeTerminal } from './NativeTerminal';

interface TerminalTab {
  id: string;
  title: string;
  shell: string;
  cwd?: string;
}

interface TerminalViewProps {
  onClose?: () => void;
  onSendToAgent?: (text: string) => void;
}

/**
 * Shells offered for new tabs, per host platform. The daemon spawns the
 * tab's shell name as a program, so offering Windows shells on Linux or
 * macOS makes every tab fail to start; the default tab is the first
 * entry, which is the platform's normal shell.
 */
const IS_WINDOWS =
  typeof navigator !== 'undefined' && /Windows/i.test(navigator.userAgent);

interface ShellOption {
  id: string;
  name: string;
  hint: string;
}

const SHELL_OPTIONS: ShellOption[] = IS_WINDOWS
  ? [
      { id: 'powershell', name: 'PowerShell', hint: 'Default' },
      { id: 'cmd', name: 'Command Prompt', hint: 'CMD' },
      { id: 'wsl', name: 'WSL / Linux', hint: 'Bash' },
      { id: 'bash', name: 'Git Bash', hint: 'sh' },
    ]
  : [
      { id: 'bash', name: 'Bash', hint: 'Default' },
      { id: 'zsh', name: 'Zsh', hint: 'zsh' },
      { id: 'sh', name: 'POSIX sh', hint: 'sh' },
    ];

export const TerminalView: React.FC<TerminalViewProps> = ({ onClose, onSendToAgent }) => {
  const [tabs, setTabs] = useState<TerminalTab[]>([
    {
      id: `tab-${SHELL_OPTIONS[0].id}-1`,
      title: `${SHELL_OPTIONS[0].name} #1`,
      shell: SHELL_OPTIONS[0].id,
    },
  ]);
  const [activeTabId, setActiveTabId] = useState<string>(
    `tab-${SHELL_OPTIONS[0].id}-1`,
  );
  const [isAddMenuOpen, setIsAddMenuOpen] = useState<boolean>(false);

  const activeTab = tabs.find((t) => t.id === activeTabId) || tabs[0];

  const handleAddTab = (shell: string, name: string) => {
    const newId = `tab-${shell}-${Date.now()}`;
    const count = tabs.filter((t) => t.shell === shell).length + 1;
    const newTab: TerminalTab = {
      id: newId,
      title: `${name} #${count}`,
      shell,
    };
    setTabs((prev) => [...prev, newTab]);
    setActiveTabId(newId);
    setIsAddMenuOpen(false);
  };

const handleCloseTab = (id: string, e: React.MouseEvent) => {
  e.stopPropagation();
  if (tabs.length === 1) return;
  const nextTabs = tabs.filter((t) => t.id !== id);
  setTabs(nextTabs);
  if (activeTabId === id) {
    setActiveTabId(nextTabs[0].id);
  }
};

return (
  <div className="flex-1 flex flex-col h-full bg-[#0d1117] rounded-2xl overflow-hidden border border-neutral-800 shadow-2xs font-sans">
    {/* ───────────────────────────────────────────────────────────
        TOP TAB BAR & CONTROLS
    ─────────────────────────────────────────────────────────── */}
    <div className="h-10 bg-[#161b22] border-b border-neutral-800 flex items-center justify-between px-2 shrink-0 select-none">
      {/* Tab list */}
      <div className="flex items-center gap-1 overflow-x-auto scrollbar-none h-full">
        {tabs.map((tab) => {
          const isActive = tab.id === activeTabId;
          return (
            <div
              key={tab.id}
              onClick={() => setActiveTabId(tab.id)}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-mono font-medium transition-all cursor-pointer border ${
                isActive
                  ? 'bg-[#0d1117] text-white border-neutral-700 shadow-xs'
                  : 'text-neutral-400 hover:text-neutral-200 hover:bg-neutral-800/60 border-transparent'
              }`}
            >
              <TerminalIcon className={`w-3.5 h-3.5 ${isActive ? 'text-blue-400' : 'text-neutral-500'}`} />
              <span className="truncate max-w-[120px]">{tab.title}</span>

              {tabs.length > 1 && (
                <button
                  onClick={(e) => handleCloseTab(tab.id, e)}
                  className="p-0.5 rounded text-neutral-500 hover:text-neutral-200 hover:bg-neutral-700/60 cursor-pointer"
                  title="Close Tab"
                >
                  <X className="w-3 h-3" />
                </button>
              )}
            </div>
          );
        })}

        {/* Add Tab Button with Dropdown */}
        <div className="relative">
          <button
            onClick={() => setIsAddMenuOpen(!isAddMenuOpen)}
            className="flex items-center gap-1 p-1.5 rounded-lg text-neutral-400 hover:text-white hover:bg-neutral-800 transition-colors cursor-pointer"
            title="Open New Terminal Shell"
          >
            <Plus className="w-3.5 h-3.5" />
            <ChevronDown className="w-3 h-3" />
          </button>

          {isAddMenuOpen && (
            <div className="absolute left-0 top-full mt-1 w-44 bg-[#1f242c] border border-neutral-700 rounded-xl shadow-xl p-1 z-30 text-xs font-mono text-neutral-200 space-y-0.5">
              {SHELL_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  onClick={() => handleAddTab(option.id, option.name)}
                  className="w-full text-left px-2.5 py-1.5 rounded-lg hover:bg-blue-600 hover:text-white transition-colors cursor-pointer flex items-center justify-between"
                >
                  <span>{option.name}</span>
                  <span className="text-[10px] text-neutral-400 font-sans">{option.hint}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Right Info Controls */}
      <div className="flex items-center gap-2">
        <span className="text-[11px] font-mono text-neutral-400 bg-neutral-800/80 px-2 py-0.5 rounded-md hidden sm:inline">
          {IS_WINDOWS ? 'Native ConPTY Engine' : 'Native PTY Engine'}
        </span>

          {onClose && (
            <button
              onClick={onClose}
              className="p-1 rounded-md text-neutral-400 hover:text-white hover:bg-neutral-800 transition-colors cursor-pointer"
              title="Close Terminal Pane"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* ───────────────────────────────────────────────────────────
          TERMINAL BODIES (Cached per tab for persistent sessions)
      ─────────────────────────────────────────────────────────── */}
      <div className="flex-1 relative overflow-hidden">
        {tabs.map((tab) => {
          const isVisible = tab.id === activeTabId;
          return (
            <div
              key={tab.id}
              className={`w-full h-full absolute inset-0 ${isVisible ? 'block z-10' : 'hidden z-0'}`}
            >
              <NativeTerminal
                shell={tab.shell}
                cwd={tab.cwd}
                title={tab.title}
                className="w-full h-full rounded-none border-none"
              />
            </div>
          );
        })}
      </div>
    </div>
  );
};

@import "tailwindcss";

/* The desktop shell is a light-only surface: the window chrome, canvases and
 * preview panels all assume a light background. Tailwind's `dark:` variant
 * defaults to `prefers-color-scheme`, which meant every view with a `dark:`
 * class silently flipped to near-white text on a dark OS setting while the
 * layout stayed light. Pinning the variant to an explicit `.dark` root that
 * nothing applies keeps every surface consistent, and a real dark theme later
 * only has to add that class to <html>. */
@custom-variant dark (&:where(.dark, .dark *));

/* Palette
 *
 * Identity lives here, not in the markup: the views already use the stock
 * Tailwind ramp (`neutral` for surfaces and text, `blue` for the accent), so
 * redefining the ramp retints the whole app without editing hundreds of class
 * names. The neutral ramp is warmed toward clay so surfaces read like paper
 * rather than a clinical cool grey, and every text step below was measured
 * against both #ffffff cards and the #faf8f5 page:
 *
 *   neutral-400 #787063  4.89:1 on white / 4.61:1 on sand  (was 2.52:1)
 *   neutral-500 #635c51  6.60:1 / 6.23:1
 *   neutral-600 #4c463d  9.33:1 / 8.80:1
 *   neutral-900 #221f1c 16.40:1 / 15.47:1
 *
 * neutral-400 is deliberately the darkest step that still passes 4.5:1 on the
 * page background; it is used for secondary metadata and cannot be lighter. */
@theme {
  --color-neutral-50: #faf8f5;
  --color-neutral-100: #f4f1ec;
  --color-neutral-200: #e8e3db;
  --color-neutral-300: #d6cfc3;
  --color-neutral-400: #787063;
  --color-neutral-500: #635c51;
  --color-neutral-600: #4c463d;
  --color-neutral-700: #3a352e;
  --color-neutral-800: #2b2721;
  --color-neutral-900: #221f1c;

  /* Sand: warm neutral surfaces and quiet fills. */
  --color-sand-50: #faf8f5;
  --color-sand-100: #f2ede4;
  --color-sand-200: #e5dccd;
  --color-sand-300: #d2c4ae;
  --color-sand-400: #b7a68c;

  /* Clay: muted terracotta for emphasis and destructive affordances. It
   * replaces saturated rose/red so warnings read as ink on paper. */
  --color-clay-50: #faf6f2;
  --color-clay-100: #f3e9e1;
  --color-clay-200: #e6d5c7;
  --color-clay-300: #d5b9a3;
  --color-clay-400: #bd9480;
  --color-clay-500: #a8775f;
  --color-clay-600: #8d5f49;
  --color-clay-700: #744c3b;
  --color-clay-800: #5d3d30;
  --color-clay-900: #4a3127;
  --color-clay-950: #33211a;

  --color-ink: #221f1c;

  /* Accent: the stock `blue` ramp is the electric product-blue every AI tool
   * ships with. This ramp keeps the hue semantics (blue = interactive) but
   * desaturates it into a slate ink, so primary buttons and links stop
   * competing with the message. Measured: blue-600 #3f5b70 is 7.14:1 on white
   * and 7.14:1 for a white label on top of it. */
  --color-blue-50: #f2f5f7;
  --color-blue-100: #e4ebf0;
  --color-blue-200: #c9d7e1;
  --color-blue-300: #a3bacb;
  --color-blue-400: #7495ad;
  --color-blue-500: #557a95;
  --color-blue-600: #3f5b70;
  --color-blue-700: #34495a;
  --color-blue-800: #2b3c49;
  --color-blue-900: #23303a;
  --color-blue-950: #17212a;

  /* Status text was failing WCAG as body-size text: emerald-600 measured
   * 3.77:1 and amber-600 3.19:1 on white. Only the two failing steps are
   * corrected; the rest of each ramp is untouched. */
  --color-emerald-600: #047857;
  --color-amber-600: #b45309;
}

/* Approval card options: a slow, low-contrast light sweep so the choices read
 * as live affordances without competing with the tool description above them.
 * The sweep is a plain gradient overlay - no box-shadow animation, which would
 * repaint on every frame - and it stops entirely under reduced motion. */
@keyframes approval-sheen {
  0% {
    transform: translateX(-120%);
    opacity: 0;
  }
  30% {
    opacity: 1;
  }
  100% {
    transform: translateX(120%);
    opacity: 0;
  }
}

.approval-option {
  position: relative;
  overflow: hidden;
}

.approval-option::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(
    100deg,
    transparent 34%,
    rgba(255, 255, 255, 0.45) 50%,
    transparent 66%
  );
  transform: translateX(-120%);
  animation: approval-sheen 3.8s ease-in-out infinite;
}

/* Stagger so the stack sweeps in sequence rather than flashing as one block. */
.approval-option:nth-child(2)::after {
  animation-delay: 0.5s;
}
.approval-option:nth-child(3)::after {
  animation-delay: 1s;
}
.approval-option:nth-child(4)::after {
  animation-delay: 1.5s;
}

@media (prefers-reduced-motion: reduce) {
  .approval-option::after {
    animation: none;
    opacity: 0;
  }
}

@layer base {
  body {
    margin: 0;
    padding: 0;
    overflow: hidden;
    height: 100vh;
    width: 100vw;
    background-color: var(--color-sand-50);
    color: var(--color-ink);
  }

